/** Einen Pokal (DFB, FA Cup oder Copa del Rey) von der aktuellen Runde an zu Ende spielen. */
function playCupToEnd(cup, sim) {
  const names = cup.names || CUP_ROUNDS;
  const rounds = cup.rounds.map((r) => ({ ...r }));
  for (let guard = 0; guard < names.length; guard++) {
    const cur = rounds[rounds.length - 1];
    cur.games = cur.games.map((g) => {
      if (cupWinner(g)) return g;
      const [hg, ag] = sim(g.h.strength, g.a.strength, cur.name === "Finale", formationTilt(g.h.form), formationTilt(g.a.form));
      return {
        ...g, hg: String(hg), ag: String(ag),
        sc: makeGoals(g.h.squad, g.a.squad, hg, ag),
        pen: hg === ag ? shootout(g.h.strength, g.a.strength) : null,
      };
    });
    if (cur.name === "Finale" || rounds.length >= names.length) break;
    const winners = cur.games.map((g) => cupWinner(g));
    const teams = [...winners, ...((cup.joiners && cup.joiners[rounds.length]) || [])];
    rounds.push({ name: names[rounds.length], games: drawPairs(teams, cup.seed + rounds.length * 31) });
  }
  return { ...cup, rounds };
}

