function euroStartTeams(id) {
  // Klubs ohne eigene Liga im Spiel (nicht DE/EN/ES) bekommen den Bereich des Wettbewerbs: stärkster = Höchstwert, schwächster = Mindestwert.
  const fremd = EURO_FOREIGN[id].filter(([name]) => !PL_NAMES.has(name) && !ES_NAMES.has(name) && !IT_NAMES.has(name));
  const fw = rescaleTo(fremd.map((x) => x[1]), EURO_RANGE[id][0], EURO_RANGE[id][1]);
  const werte = {};
  fremd.forEach(([name], i) => { werte[name] = fw[i]; });
  return [
    ...EURO_START_DE[id].map((name) => ({ name, de: true, strength: 70 })),
    ...EURO_FOREIGN[id].filter(([name]) => PL_NAMES.has(name)).map(([name]) => ({ name, de: false, en: true, strength: 70 })),
    ...EURO_FOREIGN[id].filter(([name]) => ES_NAMES.has(name)).map(([name]) => ({ name, de: false, es: true, strength: 70 })),
    ...EURO_FOREIGN[id].filter(([name]) => IT_NAMES.has(name)).map(([name]) => ({ name, de: false, it: true, strength: 70 })),
    ...fremd.map(([name]) => ({ name, de: false, strength: werte[name] })),
  ];
}

function freshEuro() {
  return {
    teams: Object.fromEntries(EURO_COMPS.map((c) => [c.id, euroStartTeams(c.id)])),
    runs: { cl: null, el: null, ecl: null },
  };
}

function normEuro(e) {
  const base = freshEuro();
  if (!e || typeof e !== "object") return base;
  const teams = {};
  const runs = {};
  EURO_COMPS.forEach((c) => {
    const l = e.teams && Array.isArray(e.teams[c.id]) ? e.teams[c.id] : null;
    teams[c.id] = l && l.length
      ? l.filter((t) => t && t.name).map((t) => ({ name: String(t.name), de: !!t.de, en: !!t.en || PL_NAMES.has(String(t.name)), es: !!t.es || ES_NAMES.has(String(t.name)), it: !!t.it || IT_NAMES.has(String(t.name)), strength: Number(t.strength) || 60 }))
      : base.teams[c.id];
    const r = e.runs && e.runs[c.id];
    runs[c.id] = r && Array.isArray(r.fixtures) && Array.isArray(r.teams) ? { ...r, ko: Array.isArray(r.ko) ? r.ko : [] } : null;
  });
  return { teams, runs };
}

/** Stärke eines Teilnehmers: deutsche Klubs zählen mit ihrer aktuellen Ligastärke. */
function euroStrength(t, active) {
  if ((t.de || t.en || t.es || t.it) && active) {
    for (const id of [...LEAGUE_IDS, ...ENG_IDS, ...ES_IDS, ...IT_IDS]) {
      const s = active[id];
      const i = s ? s.teams.indexOf(t.name) : -1;
      if (i >= 0) return Number(s.strengths[i]) || 1;
    }
  }
  return Number(t.strength) || 1;
}

/**
 * Deutsche Startplätze aus der Abschlusstabelle: Plätze 1–4 Champions League, der Pokalsieger und
 * der beste noch nicht qualifizierte Klub Europa League, der nächste Conference League.
 */
function euroQualifiers(order, cupName) {
  const cl = order.slice(0, 4);
  let rest = order.slice(4);
  const el = [];
  if (cupName && cl.indexOf(cupName) < 0) { el.push(cupName); rest = rest.filter((n) => n !== cupName); }
  while (el.length < 2 && rest.length) el.push(rest.shift());
  return { cl, el, ecl: rest.slice(0, 1) };
}

function euroApplyQualifiers(teams, q) {
  const out = {};
  EURO_COMPS.forEach((c) => {
    const fremd = (teams[c.id] || []).filter((t) => !t.de);
    out[c.id] = [...(q[c.id] || []).map((name) => ({ name, de: true, strength: 70 })), ...fremd];
  });
  return out;
}

/** Anzahl der englischen Klubs je Wettbewerb in den aktuellen Teilnehmerlisten (sonst die Standardplätze). */
function euroPlacesEn(teams) {
  const n = {};
  EURO_COMPS.forEach((c) => { n[c.id] = (teams[c.id] || []).filter((t) => t.en).length; });
  return n.cl + n.el + n.ecl > 0 ? n : { ...EURO_PLACES_EN };
}

/** Englische Plätze aus der Abschlusstabelle der Premier League: erst CL, dann EL, dann ECL. */
function euroQualifiersEn(order, places) {
  const cl = order.slice(0, places.cl);
  const el = order.slice(places.cl, places.cl + places.el);
  const ecl = order.slice(places.cl + places.el, places.cl + places.el + places.ecl);
  return { cl, el, ecl };
}

/** Teilnehmerlisten mit den neuen englischen Qualifikanten; alle übrigen Teilnehmer bleiben. */
function euroApplyQualifiersEn(teams, q) {
  const out = {};
  EURO_COMPS.forEach((c) => {
    out[c.id] = [...(teams[c.id] || []).filter((t) => !t.en),
      ...(q[c.id] || []).map((name) => ({ name, de: false, en: true, strength: 70 }))];
  });
  return out;
}

/** Europapokal-Teilnehmer nach dem Abschluss der Premier League: Plätze aus der Tabelle der Saison. */
function euroAfterEnglishSeason(d) {
  return euroAfterSeason(d, "pl", "en", EURO_PLACES_EN);
}

/** Anzahl der Klubs eines Landes (Marke `flag`) je Wettbewerb in den Teilnehmerlisten, sonst die Standardplätze. */
function euroPlaces(teams, flag, fallback) {
  const n = {};
  EURO_COMPS.forEach((c) => { n[c.id] = (teams[c.id] || []).filter((t) => t[flag]).length; });
  return n.cl + n.el + n.ecl > 0 ? n : { ...fallback };
}

/** Teilnehmerlisten mit den neuen Qualifikanten eines Landes; alle übrigen Teilnehmer bleiben. */
function euroApplyQualifiersFlag(teams, q, flag) {
  const out = {};
  EURO_COMPS.forEach((c) => {
    out[c.id] = [...(teams[c.id] || []).filter((t) => !t[flag]),
      ...(q[c.id] || []).map((name) => ({ name, de: false, [flag]: true, strength: 70 }))];
  });
  return out;
}

/** Europapokal-Teilnehmer nach dem Abschluss der Hauptliga eines Landes: Plätze aus der Tabelle der Saison. */
function euroAfterSeason(d, leagueId, flag, fallback) {
  const s = d.active[leagueId];
  const order = computeTable(s.teams, makeFixtures(s.teams.length, s.seed), s.results).map((r) => r.name);
  return { ...d.euro, teams: euroApplyQualifiersFlag(d.euro.teams, euroQualifiersEn(order, euroPlaces(d.euro.teams, flag, fallback)), flag) };
}
const euroAfterSpanishSeason = (d) => euroAfterSeason(d, "ll", "es", EURO_PLACES_ES);
const euroAfterItalianSeason = (d) => euroAfterSeason(d, "sa", "it", EURO_PLACES_IT);

/** Teilnehmerliste prüfen: genau 36 verschiedene, nicht leere Namen. */
function euroListOk(list) {
  const names = list.map((t) => String(t.name).trim());
  return list.length === EURO_SIZE && names.every(Boolean) && new Set(names).size === names.length;
}

/**
 * Kanten (Partien) auf K Spieltage verteilen, so dass jeder Klub pro Spieltag genau einmal spielt.
 * Zufälliges Färben mit Kempe-Ketten; liefert null, wenn es nicht gelingt.
 */
function colorEdges(n, edges, K, rnd) {
  for (let attempt = 0; attempt < 300; attempt++) {
    const at = Array.from({ length: n }, () => new Array(K).fill(-1));
    const col = new Array(edges.length).fill(-1);
    const setC = (e, c) => { const [u, v] = edges[e]; col[e] = c; at[u][c] = e; at[v][c] = e; };
    const unset = (e) => { const [u, v] = edges[e]; const c = col[e]; at[u][c] = -1; at[v][c] = -1; col[e] = -1; };
    const frei = (x) => { const r = []; for (let c = 0; c < K; c++) if (at[x][c] < 0) r.push(c); return r; };
    let ok = true;
    const order = shuffle(edges.map((_, i) => i), rnd);
    for (const e of order) {
      const [u, v] = edges[e];
      const fu = frei(u);
      const fv = frei(v);
      const common = fu.filter((c) => fv.indexOf(c) >= 0);
      if (common.length) { setC(e, common[Math.floor(rnd() * common.length)]); continue; }
      let done = false;
      for (let i = 0; i < fu.length && !done; i++) {
        for (let j = 0; j < fv.length && !done; j++) {
          const a = fu[i];
          const b = fv[j];
          const path = [];
          let x = v;
          let c = a;
          let trifft = false;
          while (at[x][c] >= 0) {
            const pe = at[x][c];
            path.push(pe);
            const [p, q] = edges[pe];
            x = p === x ? q : p;
            if (x === u) { trifft = true; break; }
            c = c === a ? b : a;
          }
          if (trifft) continue;
          const alt = path.map((pe) => col[pe]);
          path.forEach((pe) => unset(pe));
          path.forEach((pe, k) => setC(pe, alt[k] === a ? b : a));
          setC(e, a);
          done = true;
        }
      }
      if (!done) { ok = false; break; }
    }
    if (ok) return col;
  }
  return null;
}

/**
 * Auslosung der Ligaphase im Schweizer Modell: vier Töpfe nach Stärke, jeder Klub trifft auf zwei Gegner
 * aus jedem Topf (einmal Heim, einmal Auswärts) und spielt acht Spiele. Deutsche Klubs treffen
 * möglichst nicht aufeinander.
 */
function euroDraw(teams, seed) {
  const rnd = mulberry32(seed >>> 0);
  const order = teams.map((_, i) => i).sort((a, b) => teams[b].strength - teams[a].strength || a - b);
  const pots = [0, 1, 2, 3].map((k) => order.slice(k * 9, k * 9 + 9));
  let best = null;
  let bestScore = Infinity;
  for (let tries = 0; tries < 400 && bestScore > 0; tries++) {
    const P = pots.map((p) => shuffle(p, rnd));
    const games = [];
    for (let a = 0; a < 4; a++) {
      for (let b = a; b < 4; b++) {
        if (a === b) {
          for (let i = 0; i < 9; i++) games.push([P[a][i], P[a][(i + 1) % 9]]);
          continue;
        }
        const s = Math.floor(rnd() * 9);
        const t = (s + 1 + Math.floor(rnd() * 8)) % 9;
        for (let i = 0; i < 9; i++) {
          games.push([P[a][i], P[b][(i + s) % 9]]);
          games.push([P[b][(i + t) % 9], P[a][i]]);
        }
      }
    }
    const score = games.filter(([h, a]) => teams[h].de && teams[a].de).length;
    if (score < bestScore) { best = games; bestScore = score; }
  }
  const col = colorEdges(teams.length, best, 8, rnd);
  const fixtures = Array.from({ length: 8 }, () => []);
  if (col) {
    best.forEach((g, i) => fixtures[col[i]].push(g));
  } else {
    shuffle(best, rnd).forEach((g, i) => fixtures[Math.floor(i / 18)].push(g));
  }
  return fixtures.map((md) => shuffle(md, rnd));
}

function euroTable(run) {
  return computeTable(run.teams.map((t) => t.name), run.fixtures, run.results);
}

const numOrNull = (v) => (v === "" || v == null || !Number.isFinite(Number(v)) ? null : Number(v));

/** Gesamtergebnis eines K.-o.-Duells aus Sicht von (tie.h, tie.a); null, solange Ergebnisse fehlen. */
function tieAgg(tie, two) {
  const a1 = numOrNull(tie.l1.h);
  const b1 = numOrNull(tie.l1.a);
  if (a1 == null || b1 == null) return null;
  if (!two) return [a1, b1];
  const a2 = numOrNull(tie.l2.h);
  const b2 = numOrNull(tie.l2.a);
  if (a2 == null || b2 == null) return null;
  return [a1 + b2, b1 + a2];
}

/** "h" = tie.h kommt weiter, "a" = tie.a, null = offen. */
function tieWinner(tie, two) {
  const g = tieAgg(tie, two);
  if (!g) return null;
  if (g[0] > g[1]) return "h";
  if (g[1] > g[0]) return "a";
  return tie.pen === "h" || tie.pen === "a" ? tie.pen : null;
}

const newTie = (h, a) => ({ h, a, l1: { h: "", a: "" }, l2: { h: "", a: "" }, pen: null });

/** Playoffs: Gesetzte (Plätze 9–16) gegen Ungesetzte (17–24), Gesetzte haben das Rückspiel zu Hause. */
function euroPlayoffTies(table, rnd) {
  const at = (pos) => table[pos - 1].idx;
  const paare = [[[9, 10], [23, 24]], [[11, 12], [21, 22]], [[13, 14], [19, 20]], [[15, 16], [17, 18]]];
  const ties = [];
  paare.forEach(([s, u]) => {
    const w = rnd() < 0.5 ? u : [u[1], u[0]];
    ties.push(newTie(at(w[0]), at(s[0])));
    ties.push(newTie(at(w[1]), at(s[1])));
  });
  return ties;
}

/** Achtelfinale: Platz 1–8 gegen die Playoff-Sieger; die Reihenfolge legt den Turnierbaum fest. */
function euroR16Ties(table, playoffWinners) {
  const top = (pos) => table[pos - 1].idx;
  return [1, 8, 4, 5, 2, 7, 3, 6].map((s) => newTie(playoffWinners[8 - s], top(s)));
}

/** Nächste Runde: benachbarte Sieger spielen gegeneinander, der besser Platzierte hat das Rückspiel zu Hause. */
function euroNextTies(prev, rank) {
  const w = prev.ties.map((t) => (tieWinner(t, true) === "h" ? t.h : t.a));
  const out = [];
  for (let i = 0; i + 1 < w.length; i += 2) {
    const x = w[i];
    const y = w[i + 1];
    out.push(rank[x] > rank[y] ? newTie(x, y) : newTie(y, x));
  }
  return out;
}

function euroChampion(run) {
  if (!run || !run.ko.length) return null;
  const last = run.ko[run.ko.length - 1];
  if (last.name !== "Finale" || !last.ties[0]) return null;
  const w = tieWinner(last.ties[0], false);
  if (!w) return null;
  return run.teams[w === "h" ? last.ties[0].h : last.ties[0].a];
}

/** Spieler-Torschützen aller Partien eines Wettbewerbs (Ligaphase und K.-o.-Runden). */
function euroGames(run) {
  const out = [];
  const names = run.teams.map((t) => t.name);
  Object.keys(run.results || {}).forEach((key) => {
    const [mi, gi] = key.split(":").map(Number);
    const paar = run.fixtures[mi] && run.fixtures[mi][gi];
    if (paar) out.push({ sc: run.results[key].sc, heim: names[paar[0]], gast: names[paar[1]] });
  });
  (run.ko || []).forEach((rd) => rd.ties.forEach((t) => {
    out.push({ sc: t.l1 && t.l1.sc, heim: names[t.h], gast: names[t.a] });
    if (rd.name !== "Finale") out.push({ sc: t.l2 && t.l2.sc, heim: names[t.a], gast: names[t.h] });
  }));
  return out;
}

/** Zuordnung Spieler → Verein für die Torjägerliste. */
function euroIndex(run) {
  return squadIndex([{ teams: run.teams.map((t) => t.name), squads: run.teams.map((t) => t.squad) }]);
}

/** Kader eines Teilnehmers: deutsche Klubs bringen ihren Ligakader mit, die anderen den echten oder einen erzeugten. */
function euroSquadFor(t, strength, active) {
  if ((t.de || t.en || t.es || t.it) && active) {
    for (const id of [...LEAGUE_IDS, ...ENG_IDS, ...ES_IDS, ...IT_IDS]) {
      const s = active[id];
      const i = s ? s.teams.indexOf(t.name) : -1;
      if (i >= 0 && s.squads && s.squads[i]) return s.squads[i];
    }
  }
  return makeSquad(t.name, strength);
}

function euroArchive(compId, run) {
  const champ = euroChampion(run);
  const names = run.teams.map((t) => t.name);
  return {
    id: `${compId}-${run.label}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    type: "euro", leagueId: compId, leagueName: EURO_BY_ID[compId].name,
    label: run.label, closedAt: new Date().toISOString(),
    winner: champ ? champ.name : "—",
    scorers: scorerList(euroGames(run), euroIndex(run)).slice(0, 10),
    table: euroTable(run).map((r) => ({
      pos: r.pos, name: r.name, sp: r.sp, s: r.s, u: r.u, n: r.n, t: r.t, gt: r.gt, diff: r.diff, pkt: r.pkt,
    })),
    rounds: run.ko.map((rd) => ({
      name: rd.name,
      games: rd.ties.map((t) => {
        const g = tieAgg(t, rd.name !== "Finale") || ["", ""];
        return { h: names[t.h], a: names[t.a], hg: g[0], ag: g[1], pen: t.pen };
      }),
    })),
  };
}

/** Termine: CL dienstags, EL und ECL donnerstags (zwei Tage später); Monate ab 0 gezählt. */
const EURO_MD_DATES = [[8, 15], [8, 29], [9, 20], [10, 3], [10, 24], [11, 8], [0, 19], [0, 26]];
const EURO_KO_DATES = [[[1, 9], [1, 16]], [[2, 2], [2, 9]], [[3, 6], [3, 13]], [[3, 27], [4, 4]]];
const EURO_FINAL_DATE = { cl: [4, 29], el: [4, 26], ecl: [4, 27] };

function euroDate(label, compId, [m, d], plain) {
  const y = Number(String(label).slice(0, 4)) || 2026;
  const dt = new Date(m >= 6 ? y : y + 1, m, d);
  return compId === "cl" || plain ? dt : addDays(dt, 2);
}

/** Alle Termine eines Europapokal-Wettbewerbs für den Kalender. */
function euroEvents(compId, label) {
  const c = EURO_BY_ID[compId];
  const out = [];
  EURO_MD_DATES.forEach((md, i) => {
    out.push({ date: euroDate(label, compId, md), comp: compId, name: c.name, accent: c.accent, idx: i, ph: 0, what: `${i + 1}. Spieltag Ligaphase` });
  });
  EURO_KO_DATES.forEach((legs, r) => {
    legs.forEach((dt, k) => {
      out.push({ date: euroDate(label, compId, dt), comp: compId, name: c.name, accent: c.accent, idx: 0, ph: r + 1, what: `${EURO_KO[r]} · ${k === 0 ? "Hinspiel" : "Rückspiel"}` });
    });
  });
  out.push({ date: euroDate(label, compId, EURO_FINAL_DATE[compId], true), comp: compId, name: c.name, accent: c.accent, idx: 0, ph: 5, what: "Finale" });
  return out;
}

/** Pokalsieger der laufenden Saison (aus dem laufenden Pokal oder der Historie). */
function cupChampionName(d) {
  const c = d.cup;
  if (c && c.rounds && c.rounds.length) {
    const last = c.rounds[c.rounds.length - 1];
    if (last.name === "Finale" && last.games[0]) {
      const w = cupWinner(last.games[0]);
      if (w) return w.name;
    }
  }
  const label = d.active.bl1.label;
  const h = (d.history || []).find((x) => x.type === "cup" && x.leagueId === "cup" && x.label === label);
  return h && h.winner && h.winner !== "—" ? h.winner : null;
}

