/** Stärke einer Mannschaft direkt in der Liste eintragen; Tab springt zur nächsten Mannschaft. */
function StrengthCell({ value, index, onSet }) {
  const [txt, setTxt] = useState(String(value));
  useEffect(() => { setTxt(String(value)); }, [value]);
  const commit = () => {
    const z = parseInt(txt, 10);
    if (!Number.isFinite(z)) { setTxt(String(value)); return; }
    const ziel = Math.max(1, Math.min(100, z));
    setTxt(String(ziel));
    if (ziel !== value) onSet(index, ziel);
  };
  const key = (e) => {
    if (e.key !== "Tab" && e.key !== "Enter") return;
    commit();
    const alle = [...e.currentTarget.closest(".lr-modal, [role=dialog], body").querySelectorAll("input.lr-team-str")];
    const ziel = alle[alle.indexOf(e.currentTarget) + (e.shiftKey ? -1 : 1)];
    if (ziel) { e.preventDefault(); ziel.focus(); }
    else if (e.key === "Enter") { e.preventDefault(); e.currentTarget.blur(); }
  };
  return (
    <input className="lr-team-str" type="number" min="1" max="100" value={txt}
      aria-label={`Stärke ${index + 1}`} data-str={index}
      onChange={(e) => setTxt(e.target.value)}
      onFocus={(e) => e.target.select()}
      onBlur={commit} onKeyDown={key} />
  );
}

function TeamsModal({ season, leagueId, leagueName, onClose, onSave, onSquad, logos, onLogo, onFifa, onStrength }) {
  const [fifaStep, setFifaStep] = useState(0);
  const [fifaMsg, setFifaMsg] = useState("");
  const [fehler, setFehler] = useState("");
  const [hinweis, setHinweis] = useState("");
  const bulk = async (fileList) => {
    const files = [...(fileList || [])].filter((f) => /^image\//.test(f.type) || /\.(png|jpe?g|webp|svg|gif)$/i.test(f.name));
    if (!files.length) return;
    let ok = 0;
    const offen = [];
    for (const f of files) {
      const i = matchLogoName(f.name, season.teams);
      if (i == null) { offen.push(f.name); continue; }
      try { onLogo(season.teams[i], await logoFromFile(f)); ok++; } catch (e) { offen.push(f.name); }
    }
    setFehler("");
    setHinweis(`${ok} von ${files.length} Logos zugeordnet.` + (offen.length ? ` Nicht zugeordnet: ${offen.join(", ")}. Benenne die Dateien nach dem Verein oder füge sie unten einzeln hinzu.` : ""));
  };
  const pick = async (name, file) => {
    if (!file) return;
    try { onLogo(name, await logoFromFile(file)); setFehler(""); }
    catch (e) { setFehler("Das Bild konnte nicht gelesen werden. Bitte PNG, JPG oder WebP wählen."); }
  };
  const [names, setNames] = useState([...season.teams]);
  const bad = names.some((n) => !n.trim());
  const sauber = () => names.map((n) => n.trim());
  return (
    <Modal onClose={onClose}>
      <h2>{leagueName} — Mannschaften</h2>
      <p>
        Die Stärke trägst du hier direkt ein, mit Tab kommst du zur nächsten Mannschaft
        (Umschalt+Tab zurück). Auch Enter geht zur nächsten Mannschaft. Alle Spieler des Kaders werden dabei passend verschoben.
        Über „Kader" öffnest du die achtzehn Spieler einer Mannschaft und änderst dort
        Namen, Positionen und Einzelstärken. Namen der Vereine zu ändern ist gefahrlos,
        Spielplan und Ergebnisse hängen an der Position in der Liste.
      </p>
      <div className="lr-bulk lr-fifa">
        {fifaStep === 0 && (
          <button type="button" className="lr-btn lr-btn-sm" id="fifa-start" onClick={() => { setFifaStep(1); setFifaMsg(""); }}>
            {START_IDS.indexOf(leagueId) >= 0 ? `Startstärken setzen (${LEAGUE_BY_ID[leagueId].range[0]}–${LEAGUE_BY_ID[leagueId].range[1]})` : "Stärken nach EA FC 27 setzen"}
          </button>
        )}
        {fifaStep === 1 && (
          <>
            <button type="button" className="lr-btn lr-btn-sm lr-btn-p" id="fifa-ok"
              onClick={() => { const n = onFifa(); setFifaStep(0); setFifaMsg(START_IDS.indexOf(leagueId) >= 0 ? `${n} Klubs auf ihre Startstärke gesetzt.` : `${n} Klubs auf ihre FIFA-Stärke gesetzt.`); }}>
              Ja, Stärken überschreiben
            </button>
            <button type="button" className="lr-btn lr-btn-sm" onClick={() => setFifaStep(0)}>Abbrechen</button>
          </>
        )}
        <span className="lr-bulk-hint">
          {fifaMsg || (START_IDS.indexOf(leagueId) >= 0 ? `Setzt alle Klubs dieser Liga auf ihre Startstärken zwischen ${LEAGUE_BY_ID[leagueId].range[0]} und ${LEAGUE_BY_ID[leagueId].range[1]} zurück. Ergebnisse und Historie bleiben erhalten.` : "Gilt für Bundesliga, 2. Bundesliga und 3. Liga: Jeder Klub bekommt die Stärke, die seinem FIFA-Wert entspricht, die Abstände bleiben wie bei FIFA. Klubs der 4. und 5. Liga bleiben unverändert. Eigene Stärken und Kaderwerte dieser Klubs werden überschrieben.")}
        </span>
      </div>
      <div className="lr-bulk" onDragOver={(e) => e.preventDefault()}
        onDrop={(e) => { e.preventDefault(); bulk(e.dataTransfer && e.dataTransfer.files); }}>
        <label className="lr-btn lr-btn-sm lr-bulk-btn">
          Mehrere Logos auf einmal wählen
          <input type="file" accept="image/*" multiple id="logo-bulk" aria-label="Mehrere Logos auswählen"
            onChange={(e) => { bulk(e.target.files); e.target.value = ""; }} />
        </label>
        <span className="lr-bulk-hint">oder Dateien hierher ziehen. Der Dateiname muss zum Verein passen, z. B. „Hansa Rostock.png“ oder „Rostock.png“.</span>
      </div>
      {hinweis && <p style={{ margin: "0 0 8px", fontSize: 12 }}>{hinweis}</p>}
      <div className="lr-team-head kader"><span>Mannschaft</span><span>Logo</span><span>Stärke</span><span /></div>
      {fehler && <p style={{ margin: "0 0 8px", fontSize: 12 }}>{fehler}</p>}
      {names.map((n, i) => (
        <div className="lr-team-row kader" key={i}>
          <input className="lr-team-in" value={n} aria-label={`Mannschaft ${i + 1}`}
            onChange={(e) => { const c = [...names]; c[i] = e.target.value; setNames(c); }} />
          <span className="lr-logo-cell">
            <label className="lr-logo-pick" title={logos[season.teams[i]] ? "Logo ändern" : "Logo hinzufügen"}>
              {logos[season.teams[i]]
                ? <img src={logos[season.teams[i]]} alt={`Logo ${season.teams[i]}`} />
                : <span>+</span>}
              <input type="file" accept="image/*" id={`logo-${i}`} aria-label={`Logo für ${season.teams[i]} wählen`}
                onChange={(e) => { pick(season.teams[i], e.target.files && e.target.files[0]); e.target.value = ""; }} />
            </label>
            {logos[season.teams[i]] && (
              <button type="button" className="lr-logo-del" aria-label={`Logo von ${season.teams[i]} entfernen`}
                onClick={() => onLogo(season.teams[i], null)}>×</button>
            )}
          </span>
          <StrengthCell value={season.strengths[i]} index={i} onSet={onStrength} />
          <button className="lr-btn lr-btn-sm" disabled={bad}
            onClick={() => onSquad(i, sauber())}>Kader</button>
        </div>
      ))}
      <div className="lr-modal-foot">
        <button className="lr-btn" onClick={onClose}>Abbrechen</button>
        <button className="lr-btn lr-btn-p" disabled={bad} onClick={() => onSave(sauber())}>
          Übernehmen
        </button>
      </div>
    </Modal>
  );
}

/** Spielfeld mit der Startelf in den Linien der Formation. */
function Pitch({ squad, sel, onPick }) {
  const { gk, linien } = pitchRows(squad);
  const W = 320;
  const H = 420;
  const list = playersOf(squad);

  const reihenY = [];
  const R = linien.length;
  for (let i = 0; i < R; i++) reihenY.push(320 - (i * 250) / Math.max(1, R - 1));

  const chip = (idx, x, y) => {
    if (idx == null) return null;
    const pl = list[idx];
    if (!pl) return null;
    const aktiv = sel === idx;
    const teile = String(pl.n).trim().split(/\s+/);
    const kurz = teile[teile.length - 1].slice(0, 11);
    return (
      <g key={idx} className="lr-chip" onClick={() => onPick(idx)} role="button"
         aria-label={`${pl.n}, Stärke ${pl.s}`}>
        <circle cx={x} cy={y} r="17"
          fill={aktiv ? "var(--accent)" : "var(--board-2)"}
          stroke={aktiv ? "var(--accent)" : "rgba(233,229,216,0.5)"} strokeWidth="1.5" />
        <text x={x} y={y + 4} textAnchor="middle" fontSize="12" fontWeight="600"
          fill={aktiv ? "#fff" : "var(--chalk)"} fontFamily="'Oswald', sans-serif">{pl.s}</text>
        <text x={x} y={y + 30} textAnchor="middle" fontSize="9" fill="var(--chalk-dim)">{kurz}</text>
      </g>
    );
  };

  return (
    <svg className="lr-pitch" viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Aufstellung">
      <rect x="6" y="6" width={W - 12} height={H - 12} rx="4"
        fill="rgba(63,203,142,0.05)" stroke="rgba(233,229,216,0.22)" />
      <line x1="6" y1={H / 2} x2={W - 6} y2={H / 2} stroke="rgba(233,229,216,0.16)" />
      <circle cx={W / 2} cy={H / 2} r="42" fill="none" stroke="rgba(233,229,216,0.16)" />
      <rect x={W / 2 - 66} y={H - 60} width="132" height="54"
        fill="none" stroke="rgba(233,229,216,0.16)" />
      <rect x={W / 2 - 66} y="6" width="132" height="54"
        fill="none" stroke="rgba(233,229,216,0.16)" />

      {chip(gk, W / 2, 372)}
      {linien.map((reihe, ri) =>
        reihe.map((idx, k) => chip(idx, (W * (k + 1)) / (reihe.length + 1), reihenY[ri]))
      )}
    </svg>
  );
}

function SquadModal({ name, squad, onClose, onSave, onNavigate, autoFocusStrength }) {
  const [sq, setSq] = useState({ f: squad.f, p: squad.p.map((pl) => ({ ...pl })) });

  const upd = (i, key, val) =>
    setSq((c) => ({ ...c, p: c.p.map((pl, j) => (j === i ? { ...pl, [key]: val } : pl)) }));

  const xi = startersOf(sq);
  const bank = benchOf(sq);
  const staerke = squadStrength(sq);
  const unvollstaendig = sq.p.some((pl) => pl.s === "" || !String(pl.n).trim());

  const [sel, setSel] = useState(null);
  const [importOffen, setImportOffen] = useState(false);
  const [zielStr, setZielStr] = useState(String(staerke));
  useEffect(() => { setZielStr(String(staerke)); }, [staerke]);

  const staerkeUebernehmen = () => {
    const z = parseInt(zielStr, 10);
    if (!Number.isFinite(z)) { setZielStr(String(staerke)); return sq; }
    const ziel = Math.max(1, Math.min(100, z));
    const neu = ziel !== staerke ? scaleSquadTo(sq, ziel) : sq;
    if (neu !== sq) setSq(neu);
    setZielStr(String(ziel));
    return neu;
  };
  /** Tab springt zur nächsten Mannschaft (Umschalt+Tab zur vorherigen) und übernimmt die Stärke. */
  const tabWeiter = (e) => {
    if (e.key !== "Tab" && e.key !== "Enter") return;
    if (!onNavigate) { if (e.key === "Enter") e.currentTarget.blur(); return; }
    const neu = staerkeUebernehmen();
    if (unvollstaendig) return;
    if (onNavigate(neu, e.shiftKey && e.key === "Tab" ? -1 : 1)) e.preventDefault();
  };
  const [text, setText] = useState("");
  const erkannt = importOffen ? parseSquadText(text) : [];

  const pick = (i) => {
    if (sel == null) { setSel(i); return; }
    if (sel === i) { setSel(null); return; }
    setSq(swapPlayers(sq, sel, i));
    setSel(null);
  };

  const liste = (bench) =>
    sq.p
      .map((pl, i) => ({ pl, i }))
      .filter((x) => !!x.pl.b === bench)
      .sort((a, b) =>
        POSITIONS.indexOf(a.pl.p) - POSITIONS.indexOf(b.pl.p) ||
        (Number(b.pl.s) || 0) - (Number(a.pl.s) || 0));

  const zeile = ({ pl, i }, bench) => (
    <div className="lr-pl-row" key={i}>
      <select className="lr-team-in" value={pl.p} aria-label={`Position ${pl.n}`}
        onChange={(e) => upd(i, "p", e.target.value)}>
        {POSITIONS.map((k) => <option key={k} value={k}>{k}</option>)}
      </select>
      <input className="lr-team-in" value={pl.n} aria-label={`Name Spieler ${i + 1}`}
        onChange={(e) => upd(i, "n", e.target.value)} />
      <input className="lr-team-in num" value={pl.s} inputMode="numeric"
        aria-label={`Stärke ${pl.n}`} onFocus={(e) => e.target.select()}
        onChange={(e) => { const v = clampPlayer(e.target.value); upd(i, "s", v === "" ? "" : Number(v)); }} />
      {bench ? (
        <button className="lr-btn lr-btn-sm" data-on={sel === i ? "1" : "0"}
          onClick={() => (sel == null ? setSq(swapIn(sq, i)) : pick(i))}>
          {sel == null ? "Einwechseln" : "hierher"}
        </button>
      ) : (
        <button className="lr-btn lr-btn-sm" data-on={sel === i ? "1" : "0"} onClick={() => pick(i)}>
          {sel === i ? "gewählt" : "tauschen"}
        </button>
      )}
    </div>
  );

  return (
    <Modal onClose={onClose}>
      <h2>Kader — {name}</h2>
      <p>
        Achtzehn Spieler, elf davon in der Startelf und sieben auf der Bank. Die Stärke
        geht von 1 bis 100. Daraus errechnet sich die Teamstärke: die Startelf zählt zu
        88 Prozent, die Bank zu 12 — Kadertiefe zählt also mit, entscheidet aber nicht.
        Es geht auch andersherum: Teamstärke eintragen, dann werden alle Spieler
        gleichmäßig angehoben oder abgesenkt, das Kräfteverhältnis bleibt erhalten.
      </p>

      <div className="lr-squad-stats">
        <div className="lr-stat"><b>{Math.round(avgStr(xi) * 10) / 10}</b><span>Ø Startelf</span></div>
        <div className="lr-stat"><b>{Math.round(avgStr(bank) * 10) / 10}</b><span>Ø Bank</span></div>
        <div className="lr-stat lr-stat-main">
          <input className="lr-team-str" type="number" min="1" max="100" value={zielStr}
            aria-label="Teamstärke" id="team-staerke" autoFocus={!!autoFocusStrength}
            onChange={(e) => setZielStr(e.target.value)}
            onFocus={(e) => e.target.select()}
            onBlur={staerkeUebernehmen}
            onKeyDown={tabWeiter} />
          <span>Teamstärke</span>
        </div>
        <div className="lr-spacer" />
        <div style={{ display: "flex", flexDirection: "column", gap: 6, justifyContent: "center" }}>
          <label className="lr-prog" style={{ display: "flex", alignItems: "center", gap: 6 }}>
            Formation
            <select className="lr-jump" value={sq.f} aria-label="Formation"
              onChange={(e) => setSq(autoLineup({ ...sq, f: e.target.value }))}>
              {Object.keys(FORMATIONS).map((f) => <option key={f} value={f}>{f}</option>)}
            </select>
          </label>
          <button className="lr-btn lr-btn-sm" onClick={() => setSq(autoLineup(sq))}>
            Beste Elf aufstellen
          </button>
        </div>
      </div>

      <div className="lr-pl-sec">
        <span>Kaderliste einfügen</span>
        <button className="lr-btn lr-btn-sm" onClick={() => setImportOffen(!importOffen)}>
          {importOffen ? "schließen" : "öffnen"}
        </button>
      </div>
      {importOffen && (
        <div>
          <p style={{ marginBottom: 8 }}>
            Kader von einer Seite wie kicker.de oder Transfermarkt kopieren und hier
            einfügen — ein Spieler pro Zeile. Rückennummer und Position werden erkannt,
            egal ob durch Semikolon, Tabulator oder Leerzeichen getrennt. Steht am Ende
            einer Zeile eine Zahl von 1 bis 100, wird sie als Stärke übernommen,
            sonst bleibt die des bisherigen Spielers auf dem Platz stehen. Gib die Stärken
            am besten für alle Spieler an oder für keinen — gemischt treffen zwei
            verschiedene Maßstäbe aufeinander und die Aufstellung wird schief.
          </p>
          <textarea
            className="lr-import"
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder={"1 TW Max Müller 84\nAbwehr; Jonas Weber; 79\nLukas Schmidt"}
            aria-label="Kaderliste einfügen"
          />
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 8 }}>
            <span className="lr-tag">
              {erkannt.length} {erkannt.length === 1 ? "Spieler" : "Spieler"} erkannt
              {erkannt.length > sq.p.length ? ` — nur die ersten ${sq.p.length} werden übernommen` : ""}
            </span>
            <div className="lr-spacer" />
            <button className="lr-btn lr-btn-sm" disabled={!erkannt.length}
              onClick={() => { setSq(applySquadImport(sq, erkannt)); setText(""); setImportOffen(false); }}>
              In den Kader übernehmen
            </button>
          </div>
        </div>
      )}

      <div className="lr-pl-sec">
        <span>Aufstellung</span>
        <span className="lr-tag">{sq.f} · {tiltLabel(sq.f)}</span>
      </div>
      <Pitch squad={sq} sel={sel} onPick={pick} />
      <p className="lr-hint" style={{ paddingTop: 0 }}>
        {sel == null
          ? "Auf einen Spieler tippen, dann auf einen zweiten: zwei Startspieler tauschen die Position, ein Ersatzspieler kommt für den Angetippten ins Team."
          : `${sq.p[sel].n} ist ausgewählt — jetzt den Tauschpartner antippen.`}
      </p>

      <div className="lr-pl-sec">
        <span>Startelf</span>
        <span className="lr-tag">{xi.length} von {XI_SIZE}</span>
      </div>
      <div className="lr-pl-head"><span>Pos</span><span>Spieler</span><span>Stk</span><span /></div>
      {liste(false).map((x) => zeile(x, false))}

      <div className="lr-pl-sec">
        <span>Bank</span>
        <span className="lr-tag">{bank.length} von {BENCH_SIZE}</span>
      </div>
      <div className="lr-pl-head"><span>Pos</span><span>Spieler</span><span>Stk</span><span /></div>
      {liste(true).map((x) => zeile(x, true))}

      <div className="lr-modal-foot">
        <button className="lr-btn" onClick={onClose}>Abbrechen</button>
        <button className="lr-btn lr-btn-p" disabled={unvollstaendig}
          onClick={() => onSave({ f: sq.f, p: sq.p.map((pl) => ({ ...pl, n: String(pl.n).trim(), s: Number(pl.s) })) })}>
          Kader übernehmen
        </button>
      </div>
    </Modal>
  );
}

/* ---------------- Europapokal: Oberfläche ---------------- */

/** Teilnehmer eines Wettbewerbs bearbeiten: Vereine hinzufügen, Logos setzen, Stärken eintragen. */
function EuroTeamsModal({ comp, list, active, logos, onLogo, onSave, onClose, onQual, hasRun }) {
  const [rows, setRows] = useState(() => list.map((t) => ({ ...t, orig: t.name })));
  const [fehler, setFehler] = useState("");
  const [hinweis, setHinweis] = useState("");
  const names = rows.map((r) => r.name.trim());
  const dup = names.some((n, i) => n && names.indexOf(n) !== i);
  const leer = names.some((n) => !n);
  const bad = dup || leer;
  const setRow = (i, patch) => setRows((r) => r.map((x, k) => (k === i ? { ...x, ...patch } : x)));

  const pick = async (name, file) => {
    if (!file || !name) return;
    try { onLogo(name, await logoFromFile(file)); setFehler(""); }
    catch (e) { setFehler("Das Bild konnte nicht gelesen werden. Bitte PNG, JPG oder WebP wählen."); }
  };
  const bulk = async (fileList) => {
    const files = [...(fileList || [])].filter((f) => /^image\//.test(f.type) || /\.(png|jpe?g|webp|svg|gif)$/i.test(f.name));
    if (!files.length) return;
    let ok = 0;
    const offen = [];
    for (const f of files) {
      const i = matchLogoName(f.name, names);
      if (i == null || !names[i]) { offen.push(f.name); continue; }
      try { onLogo(names[i], await logoFromFile(f)); ok++; } catch (e) { offen.push(f.name); }
    }
    setFehler("");
    setHinweis(`${ok} von ${files.length} Logos zugeordnet.` + (offen.length ? ` Nicht zugeordnet: ${offen.join(", ")}.` : ""));
  };
  const qual = () => {
    const de = onQual();
    setRows((r) => [...de.map((name) => ({ name, de: true, strength: 70, orig: name })), ...r.filter((x) => !x.de)]);
    setHinweis("Deutsche Plätze aus der aktuellen Bundesliga-Tabelle gesetzt. Mit „Übernehmen“ speichern.");
  };
  const alleDeutschen = useMemo(() => LEAGUE_IDS.map((id) => ({ id, name: LEAGUE_BY_ID[id].name, teams: active[id] ? active[id].teams : [] })), [active]);
  const speichern = () => {
    const clean = rows.map((r) => ({ name: r.name.trim(), de: !!r.de, en: !!r.en, es: !!r.es, it: !!r.it, strength: Number(r.strength) || 60 }));
    const alt = [];
    const neu = [];
    rows.forEach((r) => {
      const n = r.name.trim();
      if (r.orig && r.orig !== n && logos[r.orig] && !logos[n]) { alt.push(r.orig); neu.push(n); }
    });
    onSave(clean, alt, neu);
  };

  return (
    <Modal onClose={onClose}>
      <h2>{comp.name} — Teilnehmer</h2>
      <p>
        Hier legst du die 36 Teilnehmer der Ligaphase fest. Die deutschen Klubs (DE) qualifizieren sich
        beim Abschluss aller Ligen automatisch über die Bundesliga-Tabelle und den DFB-Pokal, die englischen
        (EN) beim Abschluss der Premier League und die spanischen (ES) beim Abschluss der La Liga und die italienischen (IT) beim Abschluss der Serie A über deren Tabelle. Ihre Stärke kommt aus der jeweiligen Liga. Alle anderen Vereine kannst du umbenennen, austauschen, mit Logo versehen und
        mit einer Stärke belegen. Die Stärken sind Schätzungen auf der Skala der Bundesliga.
        {hasRun ? " Eine Runde läuft gerade: Namen und Stärken gelten erst ab der nächsten Auslosung, Logos sofort." : ""}
      </p>
      <div className="lr-bulk" onDragOver={(e) => e.preventDefault()}
        onDrop={(e) => { e.preventDefault(); bulk(e.dataTransfer && e.dataTransfer.files); }}>
        <label className="lr-btn lr-btn-sm lr-bulk-btn">
          Mehrere Logos auf einmal wählen
          <input type="file" accept="image/*" multiple id="eulogo-bulk" aria-label="Mehrere Logos auswählen"
            onChange={(e) => { bulk(e.target.files); e.target.value = ""; }} />
        </label>
        <span className="lr-bulk-hint">oder Dateien hierher ziehen. Der Dateiname muss zum Verein passen, z. B. „Ajax Amsterdam.png“ oder „Ajax.png“.</span>
      </div>
      <div className="lr-bulk">
        <button type="button" className="lr-btn lr-btn-sm" id="eu-qual" onClick={qual}>Deutsche Plätze aus der Bundesliga-Tabelle setzen</button>
        <button type="button" className="lr-btn lr-btn-sm" id="eu-add"
          onClick={() => setRows((r) => [...r, { name: "", de: false, strength: 60, orig: "" }])}>+ Verein hinzufügen</button>
        <span className="lr-bulk-hint" style={rows.length === EURO_SIZE ? undefined : { color: "var(--accent)" }}>
          {rows.length} von {EURO_SIZE} Teilnehmern{rows.length === EURO_SIZE ? "" : " — für die Auslosung braucht es genau 36"}
        </span>
      </div>
      {hinweis && <p style={{ margin: "0 0 8px", fontSize: 12 }}>{hinweis}</p>}
      {fehler && <p style={{ margin: "0 0 8px", fontSize: 12 }}>{fehler}</p>}
      <div className="lr-team-head kader"><span>Verein</span><span>Logo</span><span>Stärke</span><span /></div>
      {rows.map((r, i) => (
        <div className="lr-team-row kader" key={i}>
          {r.en || r.es || r.it ? (
            <select className="lr-team-in" value={r.name} aria-label={`${r.en ? "Englischer" : r.es ? "Spanischer" : "Italienischer"} Teilnehmer ${i + 1}`}
              onChange={(e) => setRow(i, { name: e.target.value })}>
              {(r.en ? ENGLAND : r.es ? SPAIN : ITALY).flatMap((g) => g.teams).map((n) => <option key={n} value={n}>{n}</option>)}
            </select>
          ) : r.de ? (
            <select className="lr-team-in" value={r.name} aria-label={`Deutscher Teilnehmer ${i + 1}`}
              onChange={(e) => setRow(i, { name: e.target.value })}>
              {!alleDeutschen.some((g) => g.teams.indexOf(r.name) >= 0) && <option value={r.name}>{r.name}</option>}
              {alleDeutschen.map((g) => (
                <optgroup key={g.id} label={g.name}>
                  {g.teams.map((n) => <option key={n} value={n}>{n}</option>)}
                </optgroup>
              ))}
            </select>
          ) : (
            <input className="lr-team-in" value={r.name} aria-label={`Verein ${i + 1}`} placeholder="Vereinsname"
              onChange={(e) => setRow(i, { name: e.target.value })} />
          )}
          <span className="lr-logo-cell">
            <label className="lr-logo-pick" title={logos[names[i]] ? "Logo ändern" : "Logo hinzufügen"}>
              {logos[names[i]] ? <img src={logos[names[i]]} alt={`Logo ${names[i]}`} /> : <span>+</span>}
              <input type="file" accept="image/*" id={`eulogo-${i}`} aria-label={`Logo für ${names[i] || "neuen Verein"} wählen`}
                onChange={(e) => { pick(names[i], e.target.files && e.target.files[0]); e.target.value = ""; }} />
            </label>
            {logos[names[i]] && (
              <button type="button" className="lr-logo-del" aria-label={`Logo von ${names[i]} entfernen`}
                onClick={() => onLogo(names[i], null)}>×</button>
            )}
          </span>
          {r.de || r.en || r.es || r.it
            ? <span className="lr-team-str" title="Stärke aus der Liga">{euroStrength(r, active)}</span>
            : <StrengthCell value={Number(r.strength) || 60} index={i} onSet={(k, v) => setRow(k, { strength: v })} />}
          {r.de || r.en || r.es || r.it
            ? <span className="lr-bulk-hint" style={{ textAlign: "center" }}>{r.en ? "EN" : r.es ? "ES" : r.it ? "IT" : "DE"}</span>
            : <button type="button" className="lr-btn lr-btn-sm" aria-label={`${names[i] || "Verein"} entfernen`}
                onClick={() => setRows((x) => x.filter((_, k) => k !== i))}>Entfernen</button>}
        </div>
      ))}
      {bad && <p style={{ margin: "8px 0 0", fontSize: 12 }}>Jeder Verein braucht einen eigenen, nicht leeren Namen.</p>}
      <div className="lr-modal-foot">
        <button className="lr-btn" onClick={onClose}>Abbrechen</button>
        <button className="lr-btn lr-btn-p" disabled={bad} onClick={speichern}>Übernehmen</button>
      </div>
    </Modal>
  );
}

/** Champions League, Europa League und Conference League. */
function EuropaTab({ data, setData, drawShare, surprise, selId, setSelId, ph, setPh, md, setMd, onTeams }) {
  const comp = EURO_BY_ID[selId];
  const euro = data.euro;
  const run = euro.runs[selId];
  const liste = euro.teams[selId];
  const [ask, setAsk] = useState(null);
  const [gm, setGm] = useState(null);
  const [km, setKm] = useState(null);
  useEffect(() => { setAsk(null); setGm(null); setKm(null); }, [selId]);

  const table = useMemo(() => (run ? euroTable(run) : []), [run]);
  const rankOf = useMemo(() => { const m = {}; table.forEach((r) => { m[r.idx] = r.pos; }); return m; }, [table]);
  const phase = run ? Math.min(ph[selId] || 0, run.ko.length) : 0;
  const mdIdx = run ? Math.min(md[selId] || 0, run.fixtures.length - 1) : 0;
  const setPhase = (i) => setPh((p) => ({ ...p, [selId]: i }));
  const champ = euroChampion(run);
  const lastKo = run && run.ko.length ? run.ko[run.ko.length - 1] : null;

  const upd = (fn) => setData((d) => {
    const r = d.euro.runs[selId];
    return r ? { ...d, euro: { ...d.euro, runs: { ...d.euro.runs, [selId]: fn(r) } } } : d;
  });

  const startOk = euroListOk(liste);
  const start = () => {
    setData((d) => {
      const teams = d.euro.teams[selId].map((t) => {
        const strength = euroStrength(t, d.active);
        const name = t.name.trim();
        return { name, de: !!t.de, en: !!t.en, es: !!t.es, it: !!t.it, strength, squad: euroSquadFor({ ...t, name }, strength, d.active) };
      });
      const seed = Math.floor(Math.random() * 1e9);
      const neu = { label: d.active.bl1.label, seed, teams, fixtures: euroDraw(teams, seed), results: {}, ko: [], rank: null };
      return { ...d, euro: { ...d.euro, runs: { ...d.euro.runs, [selId]: neu } } };
    });
    setPhase(0);
    setMd((m) => ({ ...m, [selId]: 0 }));
  };

  /* ---- Ligaphase ---- */
  const setScore = (gi, side, raw) => {
    const v = raw.replace(/[^0-9]/g, "").slice(0, 2);
    upd((r) => {
      const key = `${mdIdx}:${gi}`;
      const e = { ...(r.results[key] || { h: "", a: "" }), [side]: v };
      e.sc = trimGoals(e.sc, Number(e.h) || 0, Number(e.a) || 0);
      const next = { ...r.results, [key]: e };
      if (e.h === "" && e.a === "") delete next[key];
      return { ...r, results: next, ko: [], rank: null };
    });
  };
  const bumpScore = (gi, side, delta) => {
    upd((r) => {
      const key = `${mdIdx}:${gi}`;
      const cur = r.results[key] || { h: "", a: "" };
      const now = cur[side] === "" ? 0 : Number(cur[side]);
      const other = side === "h" ? "a" : "h";
      const e = { ...cur, [side]: String(Math.max(0, Math.min(99, now + delta))), [other]: cur[other] === "" ? "0" : cur[other] };
      e.sc = trimGoals(e.sc, Number(e.h) || 0, Number(e.a) || 0);
      return { ...r, results: { ...r.results, [key]: e }, ko: [], rank: null };
    });
  };
  const simGame = (gi) => upd((r) => {
    const [h, a] = r.fixtures[mdIdx][gi];
    const [hg, ag] = simulateMatch(r.teams[h].strength, r.teams[a].strength, false, drawShare, surprise, 0, 0);
    return { ...r, results: { ...r.results, [`${mdIdx}:${gi}`]: { h: String(hg), a: String(ag), sc: makeGoals(r.teams[h].squad, r.teams[a].squad, hg, ag) } }, ko: [], rank: null };
  });
  const simLeague = (which) => upd((r) => {
    const res = { ...r.results };
    const list = which === "all" ? r.fixtures.map((_, i) => i) : [mdIdx];
    list.forEach((i) => r.fixtures[i].forEach(([h, a], gi) => {
      if (which === "all" && parsedResult(r.results, i, gi)) return;
      const [hg, ag] = simulateMatch(r.teams[h].strength, r.teams[a].strength, false, drawShare, surprise, 0, 0);
      res[`${i}:${gi}`] = { h: String(hg), a: String(ag), sc: makeGoals(r.teams[h].squad, r.teams[a].squad, hg, ag) };
    }));
    return { ...r, results: res, ko: [], rank: null };
  });
  const clearMd = () => upd((r) => {
    const res = { ...r.results };
    r.fixtures[mdIdx].forEach((_, gi) => delete res[`${mdIdx}:${gi}`]);
    return { ...r, results: res, ko: [], rank: null };
  });
  const setStr = (idx, raw) => {
    const v = clampStrength(raw);
    const num = v === "" ? "" : Number(v);
    upd((r) => ({ ...r, teams: r.teams.map((t, i) => (i === idx ? { ...t, strength: num } : t)) }));
  };

  /* ---- K.-o.-Runden ---- */
  const editTie = (ri, ti, fn) => upd((r) => ({
    ...r,
    ko: r.ko.slice(0, ri + 1).map((rd, k) => (k === ri ? { ...rd, ties: rd.ties.map((t, j) => (j === ti ? fn(t) : t)) } : rd)),
  }));
  const setLeg = (ri, ti, leg, side, raw) => {
    const v = raw.replace(/[^0-9]/g, "").slice(0, 2);
    editTie(ri, ti, (t) => {
      const nl = { ...t[leg], [side]: v };
      nl.sc = trimGoals(nl.sc, Number(nl.h) || 0, Number(nl.a) || 0);
      return { ...t, [leg]: nl, pen: null };
    });
  };
  const bumpLeg = (ri, ti, leg, side, delta) => editTie(ri, ti, (t) => {
    const cur = t[leg];
    const now = cur[side] === "" ? 0 : Number(cur[side]);
    const other = side === "h" ? "a" : "h";
    const nl = { ...cur, [side]: String(Math.max(0, Math.min(99, now + delta))), [other]: cur[other] === "" ? "0" : cur[other] };
    nl.sc = trimGoals(nl.sc, Number(nl.h) || 0, Number(nl.a) || 0);
    return { ...t, pen: null, [leg]: nl };
  });
  const setPen = (ri, ti, side) => editTie(ri, ti, (t) => ({ ...t, pen: t.pen === side ? null : side }));
  const simTieObj = (r, rd, t) => {
    const A = r.teams[t.h];
    const B = r.teams[t.a];
    const twoLeg = rd.name !== "Finale";
    const [h1, a1] = simulateMatch(A.strength, B.strength, !twoLeg, drawShare, surprise, 0, 0);
    const nt = { ...t, l1: { h: String(h1), a: String(a1), sc: makeGoals(A.squad, B.squad, h1, a1) }, pen: null };
    if (twoLeg) {
      const [h2, a2] = simulateMatch(B.strength, A.strength, false, drawShare, surprise, 0, 0);
      nt.l2 = { h: String(h2), a: String(a2), sc: makeGoals(B.squad, A.squad, h2, a2) };
    }
    const g = tieAgg(nt, twoLeg);
    if (g[0] === g[1]) nt.pen = shootout(A.strength, B.strength);
    return nt;
  };
  const simTie = (ri, ti) => upd((r) => ({
    ...r,
    ko: r.ko.slice(0, ri + 1).map((rd, k) => (k === ri ? { ...rd, ties: rd.ties.map((t, j) => (j === ti ? simTieObj(r, rd, t) : t)) } : rd)),
  }));
  const simRound = (ri) => upd((r) => ({
    ...r,
    ko: r.ko.slice(0, ri + 1).map((rd, k) => (k === ri
      ? { ...rd, ties: rd.ties.map((t) => (tieWinner(t, rd.name !== "Finale") ? t : simTieObj(r, rd, t))) }
      : rd)),
  }));
  /** Torschützen speichern, ohne die ausgeloste K.-o.-Phase zu verwerfen. */
  const saveGoals = (g, sc) => {
    if (g.kind === "lg") {
      upd((r) => {
        const key = `${g.md}:${g.gi}`;
        return r.results[key] ? { ...r, results: { ...r.results, [key]: { ...r.results[key], sc } } } : r;
      });
    } else {
      upd((r) => ({
        ...r,
        ko: r.ko.map((rd, k) => (k !== g.ri ? rd : {
          ...rd, ties: rd.ties.map((t, j) => (j !== g.ti ? t : { ...t, [g.leg]: { ...t[g.leg], sc } })),
        })),
      }));
    }
    setGm(null);
  };
  const setKader = (idx, sq) => {
    upd((r) => ({ ...r, teams: r.teams.map((t, i) => (i === idx ? { ...t, squad: sq, strength: squadStrength(sq) } : t)) }));
    setKm(null);
  };
  const fillAll = () => upd((r) => {
    const res = { ...r.results };
    Object.keys(res).forEach((key) => {
      const [mi, gi] = key.split(":").map(Number);
      const pair = r.fixtures[mi] && r.fixtures[mi][gi];
      if (!pair || res[key].h === "" || res[key].a === "") return;
      const hg = Number(res[key].h);
      const ag = Number(res[key].a);
      if (!goalsMissing(res[key].sc, hg, ag)) return;
      res[key] = { ...res[key], sc: fillGoals(res[key].sc, r.teams[pair[0]].squad, r.teams[pair[1]].squad, hg, ag) };
    });
    const ko = r.ko.map((rd) => ({
      ...rd,
      ties: rd.ties.map((t) => {
        const fix = (leg, hi, ai) => {
          const l = t[leg];
          if (!l || l.h === "" || l.a === "") return l;
          const hg = Number(l.h);
          const ag = Number(l.a);
          if (!goalsMissing(l.sc, hg, ag)) return l;
          return { ...l, sc: fillGoals(l.sc, r.teams[hi].squad, r.teams[ai].squad, hg, ag) };
        };
        return { ...t, l1: fix("l1", t.h, t.a), l2: fix("l2", t.a, t.h) };
      }),
    }));
    return { ...r, results: res, ko };
  });
  const koComplete = (rd) => rd.ties.every((t) => tieWinner(t, rd.name !== "Finale"));
  const leagueFull = run ? run.fixtures.every((round, i) => round.every((_, gi) => parsedResult(run.results, i, gi))) : false;
  const canDraw = !!run && (run.ko.length === 0 ? leagueFull : lastKo.name !== "Finale" && koComplete(lastKo));
  const drawNext = () => {
    upd((r) => {
      const rnd = mulberry32((r.seed + 17 + r.ko.length * 31) >>> 0);
      if (!r.ko.length) {
        const tb = euroTable(r);
        const rank = {};
        tb.forEach((x) => { rank[x.idx] = x.pos; });
        return { ...r, rank, ko: [{ name: EURO_KO[0], ties: euroPlayoffTies(tb, rnd) }] };
      }
      const last = r.ko[r.ko.length - 1];
      if (last.name === "Finale" || !last.ties.every((t) => tieWinner(t, true))) return r;
      const ties = r.ko.length === 1
        ? euroR16Ties(euroTable(r), last.ties.map((t) => (tieWinner(t, true) === "h" ? t.h : t.a)))
        : euroNextTies(last, r.rank);
      return { ...r, ko: [...r.ko, { name: EURO_KO[r.ko.length], ties }] };
    });
    setPhase(run.ko.length + 1);
  };

  const closeRun = () => {
    setData((d) => {
      const r = d.euro.runs[selId];
      if (!r || !euroChampion(r)) return d;
      return { ...d, history: [euroArchive(selId, r), ...d.history], euro: { ...d.euro, runs: { ...d.euro.runs, [selId]: null } } };
    });
    setAsk(null);
    setPhase(0);
  };
  const resetRun = () => {
    setData((d) => ({ ...d, euro: { ...d.euro, runs: { ...d.euro.runs, [selId]: null } } }));
    setAsk(null);
    setPhase(0);
  };

  const filled = run ? run.fixtures.reduce((a, round, i) => a + round.filter((_, gi) => parsedResult(run.results, i, gi)).length, 0) : 0;
  const total = run ? run.fixtures.reduce((a, round) => a + round.length, 0) : 0;

  const optionsBar = (
    <>
      <label className="lr-prog" style={{ display: "flex", alignItems: "center", gap: 5 }}>
        Remis
        <select className="lr-jump" value={data.drawBias || 0} aria-label="Neigung zu Unentschieden"
          onChange={(e) => setData((d) => ({ ...d, drawBias: Number(e.target.value) }))}>
          {DRAW_LABEL.map((l, i) => <option key={l} value={i}>{l}</option>)}
        </select>
      </label>
      <label className="lr-prog" style={{ display: "flex", alignItems: "center", gap: 5 }}>
        Überraschungen
        <select className="lr-jump" value={surprise} aria-label="Häufigkeit von Überraschungen"
          onChange={(e) => setData((d) => ({ ...d, surpriseBias: Number(e.target.value) }))}>
          {FORM_LABEL.map((l, i) => <option key={l} value={i}>{l}</option>)}
        </select>
      </label>
    </>
  );

  /** Eine Partie eines K.-o.-Duells in der Optik der Ligaspiele. */
  const legRow = (ri, ti, t, leg, hIdx, aIdx, label, winnerIdx) => {
    const cls = (x) => (winnerIdx === x ? "lr-win" : winnerIdx != null ? "lr-lose" : "");
    return (
      <React.Fragment>
        <div className="lr-slot">{label}</div>
        <div className="lr-game">
          <div className="lr-game-h">
            <div className={`lr-name ${cls(hIdx)}`}><Logo name={run.teams[hIdx].name} />{run.teams[hIdx].name}<CTag t={run.teams[hIdx]} /></div>
            <TeamMeta rank={rankOf[hIdx]} strength={run.teams[hIdx].strength} name={run.teams[hIdx].name} onStrength={(v) => setStr(hIdx, v)} onKader={() => setKm(hIdx)} />
          </div>
          <div className="lr-mid">
            <div className="lr-score">
              <Stepper value={t[leg].h} team={run.teams[hIdx].name} onBump={(d) => bumpLeg(ri, ti, leg, "h", d)} />
              <ScoreBox value={t[leg].h} team={run.teams[hIdx].name} onType={(v) => setLeg(ri, ti, leg, "h", v)} />
              <span className="lr-colon">:</span>
              <ScoreBox value={t[leg].a} team={run.teams[aIdx].name} onType={(v) => setLeg(ri, ti, leg, "a", v)} />
              <Stepper value={t[leg].a} team={run.teams[aIdx].name} onBump={(d) => bumpLeg(ri, ti, leg, "a", d)} />
            </div>
            {t[leg].h !== "" && t[leg].a !== "" ? (
              <button className="lr-sim" type="button" onClick={() => setGm({ kind: "ko", ri, ti, leg })}>
                Torschützen{(t[leg].sc || []).filter((x) => x.p).length ? ` (${(t[leg].sc || []).filter((x) => x.p).length})` : ""}
              </button>
            ) : null}
          </div>
          <div className="lr-game-a">
            <div className={`lr-name ${cls(aIdx)}`}><Logo name={run.teams[aIdx].name} />{run.teams[aIdx].name}<CTag t={run.teams[aIdx]} /></div>
            <TeamMeta rank={rankOf[aIdx]} strength={run.teams[aIdx].strength} name={run.teams[aIdx].name} onStrength={(v) => setStr(aIdx, v)} onKader={() => setKm(aIdx)} />
          </div>
        </div>
      </React.Fragment>
    );
  };

  return (
    <div className="lr-wrap" style={accentVars(comp.accent)}>
      <div className="lr-rounds" style={{ paddingTop: 14 }}>
        {EURO_COMPS.map((c) => (
          <button key={c.id} className="lr-round-btn" data-on={c.id === selId ? "1" : "0"} id={`eu-${c.id}`}
            style={c.id === selId ? accentVars(c.accent) : undefined} onClick={() => setSelId(c.id)}>
            {c.name}{euro.runs[c.id] ? "" : " · nicht gestartet"}
          </button>
        ))}
      </div>

      <div className="lr-bar">
        <div className="lr-season">
          <span className="disp" style={{ fontSize: 20 }}>{comp.name}</span>
          {run ? <span className="lr-tag">{run.label}</span> : null}
          {run ? <span className="lr-tag">{filled} von {total} Spielen</span> : null}
        </div>
        <div className="lr-spacer" />
        <button className="lr-btn lr-btn-sm" id="eu-teams" onClick={onTeams}>Teilnehmer &amp; Logos</button>
        {!run && (
          <button className="lr-btn lr-btn-sm lr-btn-p" id="eu-start" disabled={!startOk} onClick={start}>Ligaphase auslosen</button>
        )}
        {run && (
          <>
            {optionsBar}
            <button className="lr-btn lr-btn-sm" id="eu-fill" onClick={fillAll}>Alle Torschützen auslosen</button>
            <button className="lr-btn lr-btn-sm" id="eu-next" disabled={!canDraw} onClick={drawNext}>
              {run.ko.length === 0 ? "Playoffs auslosen" : "Nächste Runde auslosen"}
            </button>
            {ask === "close" ? (
              <button className="lr-btn lr-btn-sm lr-btn-p" id="eu-close-ok" onClick={closeRun}>Ja, in die Historie</button>
            ) : (
              <button className="lr-btn lr-btn-sm lr-btn-p" id="eu-close" disabled={!champ} onClick={() => setAsk("close")}>Wettbewerb abschließen</button>
            )}
            {ask === "reset" ? (
              <button className="lr-btn lr-btn-sm" id="eu-reset-ok" onClick={resetRun}>Ja, alles verwerfen</button>
            ) : (
              <button className="lr-btn lr-btn-sm" id="eu-reset" onClick={() => setAsk("reset")}>Neu starten</button>
            )}
            {ask && <button className="lr-btn lr-btn-sm" onClick={() => setAsk(null)}>Abbrechen</button>}
          </>
        )}
      </div>

      {!run && (
        <>
          <p className="lr-empty">
            36 Mannschaften spielen acht Partien im Schweizer Modell: vier Töpfe nach Stärke, jeder Klub trifft auf
            zwei Gegner aus jedem Topf, je einmal zu Hause und auswärts. Die ersten Acht ziehen direkt ins Achtelfinale
            ein, die Plätze 9 bis 24 spielen Playoffs, danach folgen Achtelfinale, Viertelfinale und Halbfinale mit
            Hin- und Rückspiel und ein Finale auf neutralem Platz. Steht es nach den Rückspielen gleich, entscheidet
            das Elfmeterschießen. Die deutschen Plätze ({EURO_PLACES[selId]}) kommen automatisch aus der Liga.
            Starte den Wettbewerb mit „Ligaphase auslosen“, Vereine und Logos änderst du unter „Teilnehmer &amp; Logos“.
          </p>
          {!startOk && <p className="lr-hint" style={{ color: "var(--accent)" }}>Für die Auslosung braucht es genau 36 verschiedene Teilnehmer, aktuell {liste.length}.</p>}
          <ol className="eu-list">
            {liste.map((t, i) => (
              <li key={i}>
                <span className="eu-n">{i + 1}</span>
                <span className="eu-nm"><Logo name={t.name} />{t.name}</span>
                {t.de ? <span className="eu-de">DE</span> : t.en ? <span className="eu-de">EN</span> : t.es ? <span className="eu-de">ES</span> : t.it ? <span className="eu-de">IT</span> : null}
                <span className="eu-s">{euroStrength(t, data.active)}</span>
              </li>
            ))}
          </ol>
        </>
      )}

      {run && (
        <>
          <div className="lr-rounds">
            <button className="lr-round-btn" data-on={phase === 0 ? "1" : "0"} data-done={leagueFull ? "1" : "0"} onClick={() => setPhase(0)}>
              Ligaphase · {filled}/{total}
            </button>
            {EURO_KO.map((name, i) => (
              <button key={name} className="lr-round-btn" data-on={phase === i + 1 ? "1" : "0"}
                data-done={run.ko[i] && koComplete(run.ko[i]) ? "1" : "0"} disabled={!run.ko[i]} onClick={() => setPhase(i + 1)}>
                {name}{run.ko[i] ? ` · ${run.ko[i].ties.filter((t) => tieWinner(t, name !== "Finale")).length}/${run.ko[i].ties.length}` : ""}
              </button>
            ))}
          </div>

          {champ && (
            <div className="lr-champ-box">
              <div className="lr-tag">Sieger {comp.name} {run.label}</div>
              <div className="disp"><Logo name={champ.name} />{champ.name}</div>
            </div>
          )}

          {phase === 0 && (
            <>
              <div className="lr-md">
                <button className="lr-nav" onClick={() => setMd((m) => ({ ...m, [selId]: Math.max(0, mdIdx - 1) }))}
                  disabled={mdIdx === 0} aria-label="Vorheriger Spieltag">‹</button>
                <button className="lr-nav" onClick={() => setMd((m) => ({ ...m, [selId]: Math.min(run.fixtures.length - 1, mdIdx + 1) }))}
                  disabled={mdIdx >= run.fixtures.length - 1} aria-label="Nächster Spieltag">›</button>
                <div className="lr-md-num">{mdIdx + 1}. Spieltag <small>von {run.fixtures.length}</small></div>
                <select className="lr-jump" value={mdIdx} aria-label="Spieltag wählen"
                  onChange={(e) => setMd((m) => ({ ...m, [selId]: Number(e.target.value) }))}>
                  {run.fixtures.map((_, i) => <option key={i} value={i}>{i + 1}. Spieltag</option>)}
                </select>
                <div className="lr-spacer" />
                <button className="lr-btn lr-btn-sm" id="eu-sim-md" onClick={() => simLeague("one")}>Spieltag simulieren</button>
                <button className="lr-btn lr-btn-sm" id="eu-sim-all" onClick={() => simLeague("all")}>Rest der Ligaphase</button>
                <button className="lr-btn lr-btn-sm" onClick={clearMd}>Leeren</button>
              </div>
              <div className="lr-grid">
                <section onKeyDown={enterToNext}>
                  <h2 className="lr-sec-h">Partien</h2>
                  <p className="lr-hint">Platz und Stärke stehen unter den Namen, die Stärke lässt sich direkt ändern. Ergebnisse der Ligaphase zu ändern verwirft die ausgeloste K.-o.-Phase.</p>
                  {run.fixtures[mdIdx].map(([h, a], gi) => {
                    const r = run.results[`${mdIdx}:${gi}`] || { h: "", a: "" };
                    const done = parsedResult(run.results, mdIdx, gi);
                    const hw = done && done[0] > done[1];
                    const aw = done && done[1] > done[0];
                    return (
                      <div className="lr-game" key={gi}>
                        <div className="lr-game-h">
                          <div className={`lr-name ${hw ? "lr-win" : aw ? "lr-lose" : ""}`}><Logo name={run.teams[h].name} />{run.teams[h].name}<CTag t={run.teams[h]} /></div>
                          <TeamMeta rank={rankOf[h]} strength={run.teams[h].strength} name={run.teams[h].name} onStrength={(v) => setStr(h, v)} onKader={() => setKm(h)} />
                        </div>
                        <div className="lr-mid">
                          <div className="lr-score">
                            <Stepper value={r.h} team={run.teams[h].name} onBump={(d) => bumpScore(gi, "h", d)} />
                            <ScoreBox value={r.h} team={run.teams[h].name} onType={(v) => setScore(gi, "h", v)} />
                            <span className="lr-colon">:</span>
                            <ScoreBox value={r.a} team={run.teams[a].name} onType={(v) => setScore(gi, "a", v)} />
                            <Stepper value={r.a} team={run.teams[a].name} onBump={(d) => bumpScore(gi, "a", d)} />
                          </div>
                          {done && sensation(done[0], done[1], run.teams[h].strength, run.teams[a].strength) ? <span className="lr-sens">Sensation</span> : null}
                          <button className="lr-sim" type="button" onClick={() => simGame(gi)}>Spiel simulieren</button>
                          {done ? (
                            <button className="lr-sim" type="button" onClick={() => setGm({ kind: "lg", md: mdIdx, gi })}>
                              Torschützen{(r.sc || []).filter((x) => x.p).length ? ` (${(r.sc || []).filter((x) => x.p).length})` : ""}
                            </button>
                          ) : null}
                        </div>
                        <div className="lr-game-a">
                          <div className={`lr-name ${aw ? "lr-win" : hw ? "lr-lose" : ""}`}><Logo name={run.teams[a].name} />{run.teams[a].name}<CTag t={run.teams[a]} /></div>
                          <TeamMeta rank={rankOf[a]} strength={run.teams[a].strength} name={run.teams[a].name} onStrength={(v) => setStr(a, v)} onKader={() => setKm(a)} />
                        </div>
                      </div>
                    );
                  })}
                </section>
                <section>
                  <h2 className="lr-sec-h">Tabelle der Ligaphase</h2>
                  <Table rows={table} leagueId="eu" strengths={run.teams.map((t) => t.strength)} tags={run.teams.map((t) => euroTagOf(t))} />
                </section>
              </div>
            </>
          )}

          {phase >= 1 && run.ko[phase - 1] && (() => {
            const ri = phase - 1;
            const rd = run.ko[ri];
            const twoLeg = rd.name !== "Finale";
            return (
              <section onKeyDown={enterToNext}>
                <div className="lr-md" style={{ marginBottom: 6 }}>
                  <h2 className="lr-sec-h" style={{ border: 0, margin: 0, padding: 0 }}>{rd.name}</h2>
                  <div className="lr-spacer" />
                  <button className="lr-btn lr-btn-sm" id="eu-sim-round" onClick={() => simRound(ri)}>Runde simulieren</button>
                </div>
                <p className="lr-hint">
                  {twoLeg
                    ? "Hin- und Rückspiel, der besser platzierte Klub hat das Rückspiel zu Hause. Steht es nach beiden Spielen gleich, wählst du den Sieger im Elfmeterschießen."
                    : "Das Finale wird auf neutralem Platz in einem Spiel entschieden, bei Gleichstand per Elfmeterschießen."}
                  {" "}Erst wenn alle Duelle entschieden sind, lässt sich die nächste Runde auslosen.
                </p>
                <div className="eu-ties">
                  {rd.ties.map((t, ti) => {
                    const w = tieWinner(t, twoLeg);
                    const winnerIdx = w ? (w === "h" ? t.h : t.a) : null;
                    const agg = tieAgg(t, twoLeg);
                    const level = agg && agg[0] === agg[1];
                    return (
                      <div className="eu-tie" key={ti}>
                        {legRow(ri, ti, t, "l1", t.h, t.a, twoLeg ? "Hinspiel" : "Finale · neutraler Platz", winnerIdx)}
                        {twoLeg && legRow(ri, ti, t, "l2", t.a, t.h, "Rückspiel", winnerIdx)}
                        <div className="eu-agg">
                          {twoLeg ? (
                            <span>Gesamt <b>{agg ? `${agg[0]}:${agg[1]}` : "–:–"}</b> ({run.teams[t.h].name} : {run.teams[t.a].name})</span>
                          ) : null}
                          {w ? <span> · weiter: <b>{run.teams[winnerIdx].name}</b>{agg && agg[0] === agg[1] ? " n. E." : ""}</span> : null}
                          <button className="lr-sim" type="button" onClick={() => simTie(ri, ti)}>Duell simulieren</button>
                        </div>
                        {level && (
                          <div className="lr-pen">
                            <span className="lr-tag" style={{ alignSelf: "center" }}>Sieger n. E.:</span>
                            <button data-on={t.pen === "h" ? "1" : "0"} onClick={() => setPen(ri, ti, "h")}>{run.teams[t.h].name}</button>
                            <button data-on={t.pen === "a" ? "1" : "0"} onClick={() => setPen(ri, ti, "a")}>{run.teams[t.a].name}</button>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </section>
            );
          })()}
        </>
      )}

      {run && gm && (() => {
        let heim, gast, hg, ag, sc;
        if (gm.kind === "lg") {
          const pair = run.fixtures[gm.md] && run.fixtures[gm.md][gm.gi];
          const r = run.results[`${gm.md}:${gm.gi}`];
          if (!pair || !r) return null;
          heim = run.teams[pair[0]]; gast = run.teams[pair[1]]; hg = Number(r.h) || 0; ag = Number(r.a) || 0; sc = r.sc;
        } else {
          const t = run.ko[gm.ri] && run.ko[gm.ri].ties[gm.ti];
          if (!t) return null;
          const l = t[gm.leg];
          heim = run.teams[gm.leg === "l1" ? t.h : t.a]; gast = run.teams[gm.leg === "l1" ? t.a : t.h];
          hg = Number(l.h) || 0; ag = Number(l.a) || 0; sc = l.sc;
        }
        return (
          <GoalsModal heim={heim.name} gast={gast.name} squadH={heim.squad} squadA={gast.squad}
            hg={hg} ag={ag} sc={sc} onClose={() => setGm(null)} onSave={(x) => saveGoals(gm, x)} />
        );
      })()}

      {run && km != null && run.teams[km] && run.teams[km].squad && (
        <SquadModal key={km} name={run.teams[km].name} squad={run.teams[km].squad}
          onClose={() => setKm(null)} onSave={(sq) => setKader(km, sq)} />
      )}
    </div>
  );
}

/** Stand als Text sichern oder aus einer Sicherung wiederherstellen (funktioniert auch ohne Dateidownload). */
function BackupModal({ data, onClose, onRestore }) {
  const text = useMemo(() => JSON.stringify(data), [data]);
  const [paste, setPaste] = useState("");
  const [msg, setMsg] = useState("");
  const ref = useRef(null);
  const kopieren = async () => {
    const el = ref.current;
    if (el) { el.focus(); el.select(); }
    let ok = false;
    try { if (navigator.clipboard && navigator.clipboard.writeText) { await navigator.clipboard.writeText(text); ok = true; } } catch (e) { /* weiter */ }
    if (!ok) { try { ok = document.execCommand("copy"); } catch (e) { ok = false; } }
    setMsg(ok ? "In die Zwischenablage kopiert. Füge den Text in eine Notiz oder Datei ein." : "Der Text ist markiert: mit Strg+C (Mac: Cmd+C) kopieren.");
  };
  const wiederherstellen = () => {
    try {
      const d = JSON.parse(paste.trim());
      if (!d || !d.active) throw new Error("kein Spielstand");
      onRestore(normalize(d));
    } catch (e) {
      setMsg("Das ist keine gültige Sicherung. Bitte den ganzen Text einfügen.");
    }
  };
  return (
    <Modal onClose={onClose}>
      <h2>Sichern und wiederherstellen</h2>
      <p>
        Dein ganzer Stand (Ergebnisse, Stärken, Kader, Logos, Europapokal, Historie) als Text. Kopiere ihn
        und hebe ihn auf; damit kannst du jederzeit alles wiederherstellen, auch in einem anderen Browser.
      </p>
      <textarea ref={ref} readOnly value={text} aria-label="Sicherung"
        style={{ width: "100%", height: 90, boxSizing: "border-box", fontSize: 11, background: "var(--panel)", color: "var(--chalk)", border: "1px solid var(--line)", borderRadius: 4 }} />
      <div className="lr-modal-foot" style={{ justifyContent: "flex-start", marginTop: 8 }}>
        <button className="lr-btn lr-btn-p" id="backup-copy" onClick={kopieren}>Alles markieren und kopieren</button>
      </div>
      <h3 style={{ marginTop: 18, fontSize: 14 }}>Wiederherstellen</h3>
      <p style={{ marginTop: 4 }}>Füge hier eine zuvor kopierte Sicherung ein. Der aktuelle Stand wird dabei ersetzt.</p>
      <textarea value={paste} onChange={(e) => setPaste(e.target.value)} aria-label="Sicherung einfügen" id="backup-paste"
        style={{ width: "100%", height: 70, boxSizing: "border-box", fontSize: 11, background: "var(--panel)", color: "var(--chalk)", border: "1px solid var(--line)", borderRadius: 4 }} />
      {msg && <p style={{ margin: "8px 0 0", fontSize: 12 }}>{msg}</p>}
      <div className="lr-modal-foot">
        <button className="lr-btn" onClick={onClose}>Schließen</button>
        <button className="lr-btn lr-btn-p" id="backup-restore" disabled={!paste.trim()} onClick={wiederherstellen}>Wiederherstellen</button>
      </div>
    </Modal>
  );
}

function CloseModal({ league, season, rows, playedGames, totalGames, onClose, onConfirm, onPromotion }) {
  const n = rows.length;
  const champ = rows[0];
  const upDown = [];
  if (league.id === "sa") {
    upDown.push(["Champions League", rows.slice(0, EURO_PLACES_IT.cl)]);
    upDown.push(["Europa League", rows.slice(EURO_PLACES_IT.cl, EURO_PLACES_IT.cl + EURO_PLACES_IT.el)]);
    upDown.push(["Conference League", rows.slice(EURO_PLACES_IT.cl + EURO_PLACES_IT.el, EURO_PLACES_IT.cl + EURO_PLACES_IT.el + EURO_PLACES_IT.ecl)]);
    upDown.push(["Absteiger", rows.slice(n - 3)]);
  } else if (league.id === "sb") {
    upDown.push(["Aufsteiger", rows.slice(0, 2)]);
    upDown.push(["Playoffs (3.–6.)", rows.slice(2, 6)]);
    upDown.push(["Absteiger", rows.slice(n - 4)]);
  } else if (league.id === "sca" || league.id === "scb" || league.id === "scc") {
    upDown.push(["Aufsteiger", rows.slice(0, 1)]);
    upDown.push(["Playoffs (2.–3.)", rows.slice(1, 3)]);
  } else if (league.id === "ll") {
    upDown.push(["Champions League", rows.slice(0, EURO_PLACES_ES.cl)]);
    upDown.push(["Europa League", rows.slice(EURO_PLACES_ES.cl, EURO_PLACES_ES.cl + EURO_PLACES_ES.el)]);
    upDown.push(["Conference League", rows.slice(EURO_PLACES_ES.cl + EURO_PLACES_ES.el, EURO_PLACES_ES.cl + EURO_PLACES_ES.el + EURO_PLACES_ES.ecl)]);
    upDown.push(["Absteiger", rows.slice(n - 3)]);
  } else if (league.id === "sd") {
    upDown.push(["Aufsteiger", rows.slice(0, 2)]);
    upDown.push(["Playoffs (3.–6.)", rows.slice(2, 6)]);
    upDown.push(["Absteiger", rows.slice(n - 4)]);
  } else if (league.id === "p1" || league.id === "p2") {
    upDown.push(["Aufsteiger", rows.slice(0, 1)]);
    upDown.push(["Playoffs (2.–5.)", rows.slice(1, 5)]);
  } else if (league.id === "ch" || league.id === "l1") {
    upDown.push(["Aufsteiger", rows.slice(0, 2)]);
    upDown.push(["Playoffs (3.–6.)", rows.slice(2, 6)]);
    upDown.push(["Absteiger", rows.slice(n - (league.id === "ch" ? 3 : 4))]);
  } else if (league.id === "l2") {
    upDown.push(["Aufsteiger", rows.slice(0, 3)]);
    upDown.push(["Playoffs (4.–7.)", rows.slice(3, 7)]);
  } else if (league.id === "pl") {
    upDown.push(["Champions League", rows.slice(0, EURO_PLACES_EN.cl)]);
    upDown.push(["Europa League", rows.slice(EURO_PLACES_EN.cl, EURO_PLACES_EN.cl + EURO_PLACES_EN.el)]);
    upDown.push(["Conference League", rows.slice(EURO_PLACES_EN.cl + EURO_PLACES_EN.el, EURO_PLACES_EN.cl + EURO_PLACES_EN.el + EURO_PLACES_EN.ecl)]);
    upDown.push(["Absteiger", rows.slice(n - 3)]);
  } else if (league.id === "bl1") {
    upDown.push(["Relegation", [rows[n - 3]]]);
    upDown.push(["Absteiger", [rows[n - 2], rows[n - 1]]]);
  } else if (league.id === "bl4" || league.id === "bl5") {
    upDown.push(["Aufsteiger", rows.slice(0, 4)]);
    upDown.push(["Absteiger", rows.slice(n - 4)]);
  } else {
    upDown.push(["Aufsteiger", [rows[0], rows[1]]]);
    upDown.push(["Relegation", league.id === "bl2" ? [rows[2], rows[n - 3]] : [rows[2]]]);
    upDown.push(["Absteiger", league.id === "bl2" ? [rows[n - 2], rows[n - 1]] : rows.slice(n - 4)]);
  }
  return (
    <Modal onClose={onClose}>
      <h2>{league.name} {season.label} abschließen</h2>
      <p>
        {playedGames < totalGames
          ? `Es fehlen noch ${totalGames - playedGames} Spiele. Die Abschlusstabelle wird trotzdem so gespeichert, wie sie gerade steht.`
          : "Alle Spiele sind eingetragen."}
        {" "}Danach ändert sich die Stärke jeder Mannschaft um höchstens ±5.
      </p>
      <div style={{ borderTop: "1px solid rgba(233,229,216,0.22)", paddingTop: 14 }}>
        <div style={{ fontSize: 13, marginBottom: 12 }}>
          <span style={{ color: "#96A093" }}>{league.id === "bl1" ? "Meister" : "Erster"}:</span>{" "}
          <b>{champ ? champ.name : "—"}</b>{" "}
          <span style={{ color: "#96A093" }}>{champ ? `${champ.pkt} Punkte` : ""}</span>
        </div>
        {upDown.map(([title, list]) => (
          <div key={title} style={{ fontSize: 13, marginBottom: 8, color: "#96A093" }}>
            {title}: <span style={{ color: "#E9E5D8" }}>
              {list.filter(Boolean).map((r) => r.name).join(", ") || "—"}
            </span>
          </div>
        ))}
      </div>
      <p style={{ marginTop: 18, marginBottom: 0 }}>
        Die Saison wandert in die Historie, danach startet {league.name} {nextLabel(season.label)}{" "}
        mit denselben Mannschaften, ihren Stärkewerten und einem neuen Spielplan.
        {league.id === "pl" || league.id === "ll" || league.id === "sa" ? " Die Europapokal-Plätze gehen in die Teilnehmerlisten." : ""}{" Für echten Auf- und Abstieg nimm den zweiten Knopf."}
      </p>
      <div className="lr-modal-foot">
        <button className="lr-btn" onClick={onClose}>Abbrechen</button>
        <button className="lr-btn" onClick={onPromotion}>{ENG_IDS.indexOf(league.id) >= 0 ? "Alle englischen Ligen mit Auf- und Abstieg" : ES_IDS.indexOf(league.id) >= 0 ? "Alle spanischen Ligen mit Auf- und Abstieg" : IT_IDS.indexOf(league.id) >= 0 ? "Alle italienischen Ligen mit Auf- und Abstieg" : "Alle Ligen mit Auf- und Abstieg"}</button>
        <button className="lr-btn lr-btn-p" onClick={onConfirm}>Nur diese Liga abschließen</button>
      </div>
    </Modal>
  );
}

function PromotionModal({ data, onClose, onConfirm }) {
  const tables = useMemo(() => {
    const t = {};
    LEAGUE_IDS.forEach((id) => {
      const s = data.active[id];
      t[id] = computeTable(s.teams, makeFixtures(s.teams.length, s.seed), s.results).map((r) => r.name);
    });
    return t;
  }, [data]);

  const [duelA, setDuelA] = useState("stay");
  const [duelB, setDuelB] = useState("stay");
  const pool = data.regional || [];
  const [newcomers, setNewcomers] = useState(() => topAufsteiger(pool, 4));
  const bad = newcomers.some((n) => !n) || new Set(newcomers).size !== 4;
  const upd = (i, v) => setNewcomers((c) => c.map((x, j) => (j === i ? v : x)));
  const staerke = (n) => (pool.find((c) => c.name === n) || {}).strength;

  return (
    <Modal onClose={onClose}>
      <h2>Alle Ligen abschließen</h2>
      <p>
        Die fünf Abschlusstabellen wandern in die Historie, danach werden die Ligen neu
        besetzt. Stärkewerte nehmen die Mannschaften mit in ihre neue Liga, jede Stärke ändert sich dabei
        um höchstens ±5. In der 3., 4. und
        5. Liga steigen jeweils die ersten vier auf und die letzten vier ab.
      </p>

      {(() => {
        const q = euroQualifiers(tables.bl1, cupChampionName(data));
        return (
          <div className="lr-duel">
            <div className="lr-duel-h">
              Europapokal — die deutschen Startplätze werden automatisch vergeben
              <div style={{ fontWeight: 400, fontSize: 12, opacity: 0.75, marginTop: 2 }}>
                {EURO_COMPS.map((c) => `${c.short}: ${q[c.id].join(", ") || "—"}`).join(" · ")}
              </div>
            </div>
          </div>
        );
      })()}

      <div className="lr-duel">
        <div className="lr-duel-h">Relegation zur Bundesliga — wer spielt nächste Saison erstklassig?</div>
        <div className="lr-choice">
          <button data-on={duelA === "stay" ? "1" : "0"} onClick={() => setDuelA("stay")}>
            {tables.bl1[15] || "—"}<br />
            <span style={{ fontSize: 11, opacity: 0.7 }}>16. der Bundesliga bleibt oben</span>
          </button>
          <button data-on={duelA === "up" ? "1" : "0"} onClick={() => setDuelA("up")}>
            {tables.bl2[2] || "—"}<br />
            <span style={{ fontSize: 11, opacity: 0.7 }}>3. der 2. Bundesliga steigt auf</span>
          </button>
        </div>
      </div>

      <div className="lr-duel">
        <div className="lr-duel-h">Relegation zur 2. Bundesliga — wer spielt nächste Saison zweitklassig?</div>
        <div className="lr-choice">
          <button data-on={duelB === "stay" ? "1" : "0"} onClick={() => setDuelB("stay")}>
            {tables.bl2[15] || "—"}<br />
            <span style={{ fontSize: 11, opacity: 0.7 }}>16. der 2. Bundesliga bleibt</span>
          </button>
          <button data-on={duelB === "up" ? "1" : "0"} onClick={() => setDuelB("up")}>
            {tables.bl3[2] || "—"}<br />
            <span style={{ fontSize: 11, opacity: 0.7 }}>3. der 3. Liga steigt auf</span>
          </button>
        </div>
      </div>

      <div className="lr-duel">
        <div className="lr-duel-h">
          Vier Nachrücker aus den Regionalligen
          <div style={{ fontWeight: 400, fontSize: 12, opacity: 0.75, marginTop: 2 }}>
            Sie ersetzen {tables.bl5.slice(12).join(", ")} — diese vier wandern zurück in den
            Regionalliga-Topf und können später wieder nachrücken.
          </div>
        </div>
        <div className="lr-team-head"><span>Mannschaft</span><span>Stärke</span></div>
        {newcomers.map((n, i) => (
          <div className="lr-team-row" key={i}>
            <select className="lr-team-in" value={n} aria-label={`Nachrücker ${i + 1}`}
              onChange={(e) => upd(i, e.target.value)}>
              {pool.map((c) => (
                <option key={c.name} value={c.name}>{c.name} ({c.staffel})</option>
              ))}
            </select>
            <input className="lr-team-in num" value={staerke(n) ?? ""} readOnly
              aria-label={`Stärke Nachrücker ${i + 1}`} />
          </div>
        ))}
        {bad && <p style={{ margin: "6px 0 0", fontSize: 12 }}>Bitte vier verschiedene Vereine wählen.</p>}
      </div>

      <div className="lr-modal-foot">
        <button className="lr-btn" onClick={onClose}>Abbrechen</button>
        <button className="lr-btn lr-btn-p" disabled={bad}
          onClick={() => onConfirm(duelA, duelB, newcomers)}>
          Abschließen und neu besetzen
        </button>
      </div>
    </Modal>
  );
}

function GoalsModal({ heim, gast, squadH, squadA, hg, ag, sc, onClose, onSave }) {
  const namen = (q) => playersOf(q || { p: [] }).map((pl) => pl.n);
  const start = (seite, anzahl) => {
    const da = (sc || []).filter((g) => g.t === seite);
    return Array.from({ length: anzahl }, (_, i) => ({
      t: seite,
      p: (da[i] && da[i].p) || "",
      m: (da[i] && da[i].m != null) ? String(da[i].m) : "",
    }));
  };
  const [tore, setTore] = useState(() => [...start("h", hg), ...start("a", ag)]);
  const upd = (i, k, v) => setTore((c) => c.map((x, j) => (j === i ? { ...x, [k]: v } : x)));

  const zeile = (g, i) => (
    <div className="lr-team-row" key={i} style={{ gridTemplateColumns: "70px 1fr 56px" }}>
      <span className="lr-prog" style={{ alignSelf: "center" }}>{g.t === "h" ? "Heim" : "Gast"}</span>
      <select className="lr-team-in" value={g.p} aria-label={`Torschütze ${i + 1}`}
        onChange={(e) => upd(i, "p", e.target.value)}>
        <option value="">— unbekannt —</option>
        {namen(g.t === "h" ? squadH : squadA).map((n) => <option key={n} value={n}>{n}</option>)}
      </select>
      <input className="lr-team-in num" value={g.m} inputMode="numeric" placeholder="Min."
        aria-label={`Minute ${i + 1}`} onFocus={(e) => e.target.select()}
        onChange={(e) => upd(i, "m", e.target.value.replace(/[^0-9]/g, "").slice(0, 3))} />
    </div>
  );

  return (
    <Modal onClose={onClose}>
      <h2>Torschützen — {heim} {hg}:{ag} {gast}</h2>
      <p>
        Für jedes Tor ein Spieler und die Minute. Offen gelassene Tore zählen in keiner
        Torschützenliste mit, das Ergebnis bleibt davon unberührt.
      </p>
      {tore.length === 0 ? <p style={{ margin: 0 }}>Torloses Spiel — nichts einzutragen.</p> : null}
      {tore.map(zeile)}
      <div className="lr-modal-foot">
        {tore.length ? (
          <button className="lr-btn" onClick={() => {
            const gefuellt = fillGoals(
              tore.filter((g) => g.p).map((g) => ({ t: g.t, p: g.p, m: Number(g.m) || 0 })),
              squadH, squadA, hg, ag);
            setTore([...gefuellt.filter((g) => g.t === "h"), ...gefuellt.filter((g) => g.t === "a")]
              .map((g) => ({ t: g.t, p: g.p, m: String(g.m) })));
          }}>
            Offene auslosen
          </button>
        ) : null}
        <div className="lr-spacer" />
        <button className="lr-btn" onClick={onClose}>Abbrechen</button>
        <button className="lr-btn lr-btn-p"
          onClick={() => onSave(tore
            .filter((g) => g.p || g.m !== "")
            .map((g) => ({ t: g.t, p: g.p, m: Number(g.m) || 0 }))
            .sort((x, y) => x.m - y.m))}>
          Übernehmen
        </button>
      </div>
    </Modal>
  );
}

function RegionalModal({ regional, onClose, onSave }) {
  const [list, setList] = useState(regional.map((c) => ({ ...c, strength: String(c.strength) })));
  const upd = (i, k, v) => setList((c) => c.map((x, j) => (j === i ? { ...x, [k]: v } : x)));
  const del = (i) => setList((c) => c.filter((_, j) => j !== i));
  const add = () => setList((c) => [...c, { name: "Neuer Verein", staffel: "Nord", strength: "22", squad: null }]);
  const bad = list.some((c) => !c.name.trim() || c.strength === "");

  return (
    <Modal onClose={onClose}>
      <h2>Regionalliga-Topf</h2>
      <p>
        Das sind die Vereine unterhalb der 5. Liga. Nach jeder Saison rücken vier von ihnen in
        die 5. Liga nach, und aus ihm kommen die Absteiger der 5. Liga und neue Klubs. Wer aus der
        5. Liga absteigt, landet automatisch wieder hier — mit seinem Kader, damit er bei einer
        Rückkehr vollständig ist.
      </p>
      <div className="lr-team-head"><span>Verein</span><span>Staffel</span><span>Stärke</span><span /></div>
      {list.map((c, i) => (
        <div className="lr-team-row" key={i} style={{ gridTemplateColumns: "1fr 110px 52px 40px" }}>
          <input className="lr-team-in" value={c.name} aria-label={`Verein ${i + 1}`}
            onChange={(e) => upd(i, "name", e.target.value)} />
          <select className="lr-team-in" value={c.staffel} aria-label={`Staffel ${i + 1}`}
            onChange={(e) => upd(i, "staffel", e.target.value)}>
            {STAFFELN.map((st) => <option key={st} value={st}>{st}</option>)}
            <option value="—">—</option>
          </select>
          <input className="lr-team-in num" value={c.strength} inputMode="numeric"
            aria-label={`Stärke ${i + 1}`} onFocus={(e) => e.target.select()}
            onChange={(e) => upd(i, "strength", clampStrength(e.target.value))} />
          <button className="lr-btn lr-btn-sm" onClick={() => del(i)} aria-label={`${c.name} entfernen`}>×</button>
        </div>
      ))}
      <div className="lr-modal-foot">
        <button className="lr-btn" onClick={add}>Verein hinzufügen</button>
        <div className="lr-spacer" />
        <button className="lr-btn" onClick={onClose}>Abbrechen</button>
        <button className="lr-btn lr-btn-p" disabled={bad}
          onClick={() => onSave(list.map((c) => ({ ...c, name: c.name.trim(), strength: Number(c.strength) })))}>
          Übernehmen
        </button>
      </div>
    </Modal>
  );
}

function CupStartModal({ onClose, onStart, unten }) {
  // Die acht Amateurplätze gehen an die acht Bestplatzierten der 4. Liga.
  const bl4 = (unten || []).filter(Boolean)[0];
  const ziehen = () => {
    if (!bl4 || !bl4.teams.length) return DEFAULT_AMATEURS.map((n, i) => ({ name: n, strength: String(24 - i) }));
    const rows = computeTable(bl4.teams, makeFixtures(bl4.teams.length, bl4.seed), bl4.results);
    const stark = (name) => Number((bl4.strengths || [])[bl4.teams.indexOf(name)]) || 22;
    // Vor dem ersten Spieltag gibt es noch keine Tabelle: dann entscheidet die Stärke.
    const order = rows.every((r) => r.sp === 0) ? [...rows].sort((x, y) => stark(y.name) - stark(x.name)) : rows;
    return order.slice(0, 8).map((r) => ({ name: r.name, strength: String(stark(r.name)) }));
  };
  const [amateurs, setAmateurs] = useState(ziehen);
  const bad = amateurs.some((a) => !a.name.trim() || a.strength === "");
  const upd = (i, k, v) => setAmateurs((c) => c.map((x, j) => (j === i ? { ...x, [k]: v } : x)));
  return (
    <Modal onClose={onClose}>
      <h2>DFB-Pokal auslosen</h2>
      <p>
        Die 56 Klubs der drei Profiligen sind gesetzt, mit ihren aktuellen Stärkewerten. Dazu
        kommen die acht Bestplatzierten der 4. Liga (vor dem ersten Spieltag die acht stärksten) —
        überschreiben kannst du sie trotzdem.
      </p>
      <div className="lr-pl-sec">
        <span>Die acht Ersten der 4. Liga</span>
        <button className="lr-btn lr-btn-sm" onClick={() => setAmateurs(ziehen())}>zurücksetzen</button>
      </div>
      <div className="lr-team-head"><span>Regionalligist</span><span>Stärke</span></div>
      {amateurs.map((a, i) => (
        <div className="lr-team-row" key={i}>
          <input className="lr-team-in" value={a.name} aria-label={`Amateurklub ${i + 1}`}
            onChange={(e) => upd(i, "name", e.target.value)} />
          <input className="lr-team-in num" value={a.strength} inputMode="numeric"
            aria-label={`Stärke Amateurklub ${i + 1}`} onFocus={(e) => e.target.select()}
            onChange={(e) => upd(i, "strength", clampStrength(e.target.value))} />
        </div>
      ))}
      <div className="lr-modal-foot">
        <button className="lr-btn" onClick={onClose}>Abbrechen</button>
        <button className="lr-btn lr-btn-p" disabled={bad}
          onClick={() => onStart(amateurs.map((a) => ({ name: a.name.trim(), strength: Number(a.strength) })))}>
          1. Runde auslosen
        </button>
      </div>
    </Modal>
  );
}

/* ---------------- Liveticker ---------------- */

/** Ein Spiel dauert im Ticker zwei Minuten Echtzeit (= 90 Spielminuten). */
const LIVE_SECONDS = 120;

/** Fehlende Torschützen mit Minute auffüllen, damit der Ticker immer zum Endstand passt. */
function liveGoals(sc, hg, ag) {
  const out = (sc || []).map((g) => ({ ...g, m: g.m || 1 + Math.floor(Math.random() * 90) }));
  [["h", hg], ["a", ag]].forEach(([t, n]) => {
    for (let k = out.filter((g) => g.t === t).length; k < n; k++) out.push({ t, p: "", m: 1 + Math.floor(Math.random() * 90) });
  });
  return out.sort((x, y) => x.m - y.m);
}

function LiveTicker({ games, season, fixtures, mdIdx, onClose, onFinish }) {
  const [elapsed, setElapsed] = useState(0);
  const [running, setRunning] = useState(false);
  const last = useRef(0);

  useEffect(() => {
    if (!running) return undefined;
    last.current = Date.now();
    const id = setInterval(() => {
      const now = Date.now();
      const dt = (now - last.current) / 1000;
      last.current = now;
      setElapsed((e) => Math.min(LIVE_SECONDS, e + dt));
    }, 200);
    return () => clearInterval(id);
  }, [running]);

  const done = elapsed >= LIVE_SECONDS;
  useEffect(() => { if (done) setRunning(false); }, [done]);
  const minute = done ? 90 : Math.floor((elapsed / LIVE_SECONDS) * 90);

  // Torfolge je Spiel mit laufendem Zwischenstand.
  const events = useMemo(() => games.flatMap((g, gi) => {
    let h = 0, a = 0;
    return [...g.sc].sort((x, y) => x.m - y.m).map((e) => {
      if (e.t === "h") h++; else a++;
      return { m: e.m, gi, e, score: `${h}:${a}` };
    });
  }).sort((x, y) => x.m - y.m), [games]);

  const stand = (gi) => {
    const sofar = events.filter((x) => x.gi === gi && x.m <= minute);
    const h = sofar.filter((x) => x.e.t === "h").length;
    return { h, a: sofar.length - h };
  };

  const res = { ...season.results };
  if (minute >= 1) games.forEach((g, gi) => { const st = stand(gi); res[`${mdIdx}:${g.gi}`] = { h: String(st.h), a: String(st.a) }; });
  const rows = computeTable(season.teams, fixtures, res);
  const shown = events.filter((x) => x.m <= minute).reverse();
  const clock = (sec) => `${Math.floor(sec / 60)}:${String(Math.floor(sec % 60)).padStart(2, "0")}`;

  return (
    <Modal onClose={elapsed > 0 && !done ? () => {} : onClose}>
      <div className="lr-live">
        <h2>Liveticker — {mdIdx + 1}. Spieltag</h2>
        <p>
          Alle offenen Spiele laufen gleichzeitig, ein Spiel dauert zwei Minuten. Die Ergebnisse
          werden erst gespeichert, wenn du sie am Ende übernimmst.
        </p>
        <div className="lr-live-bar">
          <span className="lr-live-min" id="live-min">{done ? "Abpfiff" : `${minute}. Minute`}</span>
          <div className="lr-live-track"><div style={{ width: `${(elapsed / LIVE_SECONDS) * 100}%` }} /></div>
          <span className="lr-status">{clock(elapsed)} / {clock(LIVE_SECONDS)}</span>
        </div>
        <div className="lr-live-grid">
          <div>
            <div className="lr-pl-sec"><span>Spiele</span></div>
            {games.map((g, gi) => {
              const st = stand(gi);
              const treffer = events.some((x) => x.gi === gi && x.m <= minute && x.m > minute - 3);
              return (
                <div className="lr-live-game" key={g.gi} data-goal={treffer && !done ? "1" : "0"}>
                  <span className="lr-live-t r"><span>{season.teams[g.h]}</span><Logo name={season.teams[g.h]} /></span>
                  <b className="lr-live-sc">{minute < 1 ? "–" : `${st.h}:${st.a}`}</b>
                  <span className="lr-live-t"><Logo name={season.teams[g.a]} /><span>{season.teams[g.a]}</span></span>
                </div>
              );
            })}
            <div className="lr-pl-sec" style={{ marginTop: 14 }}><span>Torfolge</span></div>
            <div className="lr-live-feed" id="live-feed">
              {!shown.length && <p className="lr-empty">Noch kein Tor gefallen.</p>}
              {shown.map((x, i) => (
                <div key={i} className="lr-live-ev">
                  <b>{x.m}'</b>
                  <span>Tor {season.teams[x.e.t === "h" ? games[x.gi].h : games[x.gi].a]}{x.e.p ? ` — ${x.e.p}` : ""}</span>
                  <small>{season.teams[games[x.gi].h]} {x.score} {season.teams[games[x.gi].a]}</small>
                </div>
              ))}
            </div>
          </div>
          <div>
            <div className="lr-pl-sec"><span>Tabelle live</span></div>
            <table className="lr-live-tab">
              <thead><tr><th>#</th><th>Mannschaft</th><th>Sp</th><th>Diff</th><th>Pkt</th></tr></thead>
              <tbody>
                {rows.map((r, i) => (
                  <tr key={r.name}>
                    <td>{i + 1}</td>
                    <td><Logo name={r.name} />{r.name}</td>
                    <td>{r.sp}</td>
                    <td>{r.diff > 0 ? `+${r.diff}` : r.diff}</td>
                    <td><b>{r.pkt}</b></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
        <div className="lr-modal-foot">
          <button className="lr-btn" onClick={onClose}>Abbrechen</button>
          {!done && (
            <button className="lr-btn" id="live-skip" onClick={() => { setElapsed(LIVE_SECONDS); setRunning(false); }}>Sofort beenden</button>
          )}
          {!done && (
            <button className="lr-btn lr-btn-p" id="live-start" onClick={() => setRunning((r) => !r)}>
              {running ? "Pause" : elapsed > 0 ? "Weiter" : "Anpfiff"}
            </button>
          )}
          {done && <button className="lr-btn lr-btn-p" id="live-take" onClick={onFinish}>Ergebnisse übernehmen</button>}
        </div>
      </div>
    </Modal>
  );
}

/* ---------------- England im Europapokal ---------------- */

/** Wie weit ist ein Klub im laufenden Europapokal? Ohne laufende Runde: qualifiziert. */
function euroClubStatus(run, name) {
  if (!run) return "qualifiziert, Runde noch nicht gestartet";
  const idx = run.teams.findIndex((t) => t.name === name);
  if (idx < 0) return "in dieser Runde nicht dabei";
  const row = euroTable(run).find((r) => r.idx === idx);
  const phase = `Ligaphase: Platz ${row.pos}, ${row.pkt} Punkte nach ${row.sp} Spielen`;
  if (!run.ko.length) return phase;
  let status = null;
  for (const rd of run.ko) {
    const two = rd.name !== "Finale";
    const tie = rd.ties.find((t) => t.h === idx || t.a === idx);
    if (!tie) continue;
    const w = tieWinner(tie, two);
    if (!w) { status = `spielt im ${rd.name}`; break; }
    if ((w === "h" ? tie.h : tie.a) !== idx) { status = `ausgeschieden im ${rd.name}`; break; }
    status = rd.name === "Finale" ? "Sieger" : `${rd.name} gewonnen`;
  }
  if (!status) status = row.pos <= 8 ? "direkt im Achtelfinale" : "ausgeschieden in der Ligaphase";
  return `${phase} · ${status}`;
}

/** Welche Klubs eines Landes spielen in CL, EL und ECL, und wer qualifiziert sich nach der aktuellen Tabelle? */
function CountryEuropa({ data, cty }) {
  const top = data.active[cty.top];
  const gespielt = Object.keys(top.results).length > 0;
  const tabelle = computeTable(top.teams, makeFixtures(top.teams.length, top.seed), top.results).map((r) => r.name);
  const spaeter = euroQualifiersEn(tabelle, euroPlaces(data.euro.teams, cty.flag, cty.places));
  const p = cty.places;
  return (
    <div className="lr-wrap">
      <section style={accentVars("#4C8BF5")}>
        <h2>Europapokal — {cty.name}</h2>
        <p className="lr-hint">
          Diese Klubs der {cty.topName} spielen in der Europapokal-Saison mit. Stärke und Kader kommen
          live aus der Liga. Für die nächste Saison zählt die Tabelle der {cty.topName}: Plätze
          {" "}1–{p.cl} Champions League, {p.cl + 1}–{p.cl + p.el} Europa League,
          {" "}{p.cl + p.el + 1}{p.ecl > 1 ? `–${p.cl + p.el + p.ecl}` : ""} Conference League.
        </p>
        <div className="lr-top-grid">
          {EURO_COMPS.map((c) => {
            const liste = (data.euro.teams[c.id] || []).filter((t) => t[cty.flag]);
            const run = data.euro.runs[c.id];
            return (
              <div key={c.id} data-comp={c.id}>
                <div className="lr-top-h" style={{ "--accent": c.accent }}>
                  <b>{c.name}</b>
                  <span>{liste.length} aus {cty.name}</span>
                </div>
                <ol className="eu-eng">
                  {liste.map((t, i) => (
                    <li key={t.name}>
                      <span className="eu-n">{i + 1}</span>
                      <span className="eu-nm"><Logo name={t.name} />{t.name}</span>
                      <span className="eu-s">{euroStrength(t, data.active)}</span>
                      <small>{euroClubStatus(run, t.name)}</small>
                    </li>
                  ))}
                </ol>
                {gespielt && spaeter[c.id].length > 0 && (
                  <p className="lr-hint" style={{ marginTop: 10 }}>
                    Nach der aktuellen Tabelle in der nächsten Saison: {spaeter[c.id].join(", ")}.
                  </p>
                )}
              </div>
            );
          })}
        </div>
      </section>
    </div>
  );
}

/* ================================================================== */
/*  Kalender                                                          */
/* ================================================================== */

function Kalender({ data, onJump, section }) {
  const [filter, setFilter] = useState("alle");

  const events = useMemo(() => {
    const out = [];
    const eng = section !== "de";
    COUNTRY[section].ids.forEach((id) => {
      const s = data.active[id];
      const count = s.teams.length * 2 - 2;
      matchdayDates(s.start, count).forEach((d, i) => {
        out.push({ date: d, comp: id, name: LEAGUE_BY_ID[id].name, accent: LEAGUE_BY_ID[id].accent, idx: i, what: `${i + 1}. Spieltag` });
      });
    });
    if (eng && data[COUNTRY[section].cupKey]) {
      const cu = data[COUNTRY[section].cupKey];
      cu.rounds.forEach((r, i) => {
        out.push({ date: cupRoundDate(cu.label, i, COUNTRY[section].cupKey), comp: COUNTRY[section].cupKey, name: COUNTRY[section].cupName, accent: COUNTRY[section].cupAccent, idx: i, what: r.name });
      });
    }
    if (!eng && data.cup) {
      data.cup.rounds.forEach((r, i) => {
        out.push({ date: cupRoundDate(data.cup.label, i, "cup"), comp: "cup", name: "DFB-Pokal", accent: CUP_ACCENT, idx: i, what: r.name });
      });
    }
    if (!eng) {
      EURO_COMPS.forEach((c) => {
        const run = data.euro && data.euro.runs[c.id];
        euroEvents(c.id, run ? run.label : data.active.bl1.label).forEach((e) => out.push(e));
      });
    }
    return out.sort((a, b) => a.date - b.date);
  }, [data, section]);

  const shown = filter === "alle" ? events : events.filter((e) => e.comp === filter);

  const months = [];
  shown.forEach((e) => {
    const key = `${e.date.getFullYear()}-${e.date.getMonth()}`;
    const last = months[months.length - 1];
    if (last && last.key === key) last.items.push(e);
    else months.push({ key, title: `${MONTHS[e.date.getMonth()]} ${e.date.getFullYear()}`, items: [e] });
  });

  return (
    <>
      <div className="lr-bar">
        <h2 className="disp" style={{ fontSize: 20 }}>Kalender</h2>
        <div className="lr-spacer" />
        <label className="lr-prog" style={{ display: "flex", alignItems: "center", gap: 5 }}>
          Wettbewerb
          <select className="lr-jump" value={filter} onChange={(e) => setFilter(e.target.value)}
            aria-label="Wettbewerb filtern">
            <option value="alle">alle</option>
            {COUNTRY[section].leagues.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
            <option value={COUNTRY[section].cupKey}>{COUNTRY[section].cupName}</option>
            {section === "de" && EURO_COMPS.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        </label>
      </div>

      <p className="lr-hint" style={{ paddingBottom: 12 }}>
        {section !== "de"
          ? `Alle Termine der ${COUNTRY[section].topName}, nach Monat sortiert. Der Spielplan folgt demselben
        Rhythmus wie in Deutschland: Pause vom 20. Dezember bis zum 9. Januar und in den vier
        Länderspielpausen im September, Oktober, November und März. Ein Klick springt zum Spieltag.`
          : `Alle Termine der Saison, nach Monat sortiert. Gespielt wird nicht über die
        Winterpause vom 20. Dezember bis zum 9. Januar und nicht in den vier
        Länderspielpausen im September, Oktober, November und März. Die Europapokale
        spielen dienstags (Champions League) und donnerstags (Europa und Conference League).
        Ein Klick springt zum Spieltag.`}
      </p>

      {months.map((m) => (
        <div className="lr-cal-month" key={m.key}>
          <h3>{m.title}</h3>
          {m.items.map((e, i) => (
            <button className="lr-cal-row" key={i} onClick={() => onJump(e.comp, e.idx, e)}>
              <span className="lr-cal-bar" style={{ background: e.accent }} />
              <span className="lr-cal-date">{fmtShort(e.date)}</span>
              <span className="lr-cal-what">{e.what}</span>
              <span className="lr-cal-comp">{e.name}</span>
            </button>
          ))}
        </div>
      ))}
    </>
  );
}

/* ================================================================== */
/*  Historie                                                          */
/* ================================================================== */

function Historie({ history, open, setOpen, onExport, onBackup, onReset, onPromotion, onRestart, onRegional, section }) {
  const [filter, setFilter] = useState("all");
  const titles = useMemo(() => {
    const out = { cup: {}, facup: {}, copa: {}, coppa: {}, cl: {}, el: {}, ecl: {} };
    [...LEAGUES, ...ENGLAND, ...SPAIN, ...ITALY].forEach((l) => { out[l.id] = {}; });
    history.forEach((h) => {
      if (h.type === "euro") {
        if (h.winner && h.winner !== "—" && out[h.leagueId]) out[h.leagueId][h.winner] = (out[h.leagueId][h.winner] || 0) + 1;
        return;
      }
      if (h.type === "cup") {
        if (h.winner && out[h.leagueId]) out[h.leagueId][h.winner] = (out[h.leagueId][h.winner] || 0) + 1;
        return;
      }
      const first = h.table && h.table[0];
      if (!first || !out[h.leagueId]) return;
      out[h.leagueId][first.name] = (out[h.leagueId][first.name] || 0) + 1;
    });
    return out;
  }, [history]);

  const boards = (section !== "de"
    ? [...COUNTRY[section].leagues.map((l) => ({ key: l.id, accent: l.accent, head: `Meisterschaften — ${l.name}` })),
      { key: COUNTRY[section].cupKey, accent: COUNTRY[section].cupAccent, head: `Pokalsiege — ${COUNTRY[section].cupName}` }]
    : [
      ...LEAGUES.map((l) => ({
        key: l.id, accent: l.accent,
        head: `${l.id === "bl1" ? "Meisterschaften" : "Titel"} — ${l.name}`,
      })),
      { key: "cup", accent: CUP_ACCENT, head: "Pokalsiege — DFB-Pokal" },
      ...EURO_COMPS.map((c) => ({ key: c.id, accent: c.accent, head: `Titel — ${c.name}` })),
    ]).filter((b) => Object.keys(titles[b.key]).length > 0);

  /** Einträge nach Wettbewerb ordnen, jeweils die neueste Saison zuerst. */
  const groups = useMemo(() => {
    const defs = section !== "de"
      ? [...COUNTRY[section].leagues.map((l) => ({ key: l.id, name: l.name, accent: l.accent })), { key: COUNTRY[section].cupKey, name: COUNTRY[section].cupName, accent: COUNTRY[section].cupAccent }]
      : [
        ...LEAGUES.map((l) => ({ key: l.id, name: l.name, accent: l.accent })),
        { key: "cup", name: "DFB-Pokal", accent: CUP_ACCENT },
        ...EURO_COMPS.map((c) => ({ key: c.id, name: c.name, accent: c.accent })),
      ];
    const keyOf = (h) => h.leagueId;
    return defs
      .map((d) => ({
        ...d,
        items: history
          .filter((h) => keyOf(h) === d.key)
          .sort((a, b) => String(b.label).localeCompare(String(a.label)) || String(b.closedAt).localeCompare(String(a.closedAt))),
      }))
      .filter((d) => d.items.length > 0);
  }, [history]);

  return (
    <>
      <div className="lr-bar">
        <h2 className="disp" style={{ fontSize: 20 }}>Historie</h2>
        <div className="lr-spacer" />
        {section === "de" && <button className="lr-btn lr-btn-sm" onClick={onPromotion}>Alle Ligen abschließen</button>}
        {section === "de" && <button className="lr-btn lr-btn-sm" onClick={onRegional}>Regionalliga-Topf</button>}
        <button className="lr-btn lr-btn-sm" id="backup-open" onClick={onBackup}>Sichern</button>
        <button className="lr-btn lr-btn-sm" onClick={onExport}>Exportieren</button>
        <button className="lr-btn lr-btn-sm" onClick={onRestart}>Neu beginnen</button>
        <button className="lr-btn lr-btn-sm" onClick={onReset}>Alles zurücksetzen</button>
      </div>

      {!history.length && (
        <p className="lr-empty">
          Noch keine abgeschlossene Saison. Sobald du eine Liga oder den Pokal abschließt,
          landet das Ergebnis hier und bleibt dauerhaft gespeichert.
        </p>
      )}

      {boards.length > 0 && (
        <div className="lr-titles" style={{ marginTop: 26 }}>
          {boards.map((b) => {
            const entries = Object.entries(titles[b.key])
              .sort((x, y) => y[1] - x[1] || x[0].localeCompare(y[0], "de"));
            return (
              <div key={b.key}>
                <h3 style={{ borderBottomColor: b.accent }}>{b.head}</h3>
                <ol>
                  {entries.map(([name, count]) => (
                    <li key={name}><span>{name}</span><span>{count}×</span></li>
                  ))}
                </ol>
              </div>
            );
          })}
        </div>
      )}

      {history.length > 0 && (
        <div className="lr-rounds" style={{ paddingTop: 18 }}>
          <button className="lr-round-btn" data-on={filter === "all" ? "1" : "0"} onClick={() => setFilter("all")}>Alle</button>
          {groups.map((g) => (
            <button key={g.key} className="lr-round-btn" data-on={filter === g.key ? "1" : "0"}
              style={filter === g.key ? accentVars(g.accent) : undefined} onClick={() => setFilter(g.key)}>
              {g.name} · {g.items.length}
            </button>
          ))}
        </div>
      )}

      {groups.filter((g) => filter === "all" || filter === g.key).map((g) => (
      <div key={g.key} className="lr-hist-group">
      <h3 className="lr-hist-group-h" style={{ borderBottomColor: g.accent }}>{g.name}</h3>
      {g.items.map((h) => {
        const isEuro = h.type === "euro";
        const isCup = h.type === "cup" || isEuro;
        const l = LEAGUE_BY_ID[h.leagueId];
        const accent = isEuro && EURO_BY_ID[h.leagueId] ? EURO_BY_ID[h.leagueId].accent : isCup ? CUP_ACCENT : l ? l.accent : "#C9C3B0";
        const isOpen = open === h.id;
        const champ = isCup ? h.winner : h.table && h.table[0] ? h.table[0].name : "—";
        return (
          <div key={h.id}>
            <button className="lr-hist-row" onClick={() => setOpen(isOpen ? null : h.id)}>
              <span className="lr-hist-season">{h.label}</span>
              <span className="lr-hist-league" style={{ color: accent }}>{h.leagueName}</span>
              <span className="lr-hist-champ">
                <b>{champ}</b>
                {!isCup && h.table && h.table[0] ? (
                  <span style={{ color: "#96A093" }}> · {h.table[0].pkt} Punkte</span>
                ) : null}
              </span>
              <span className="lr-hist-open">{isOpen ? "schließen" : isCup ? "Turnierbaum" : "Tabelle"}</span>
            </button>
            {isOpen && (
              <div className="lr-hist-body" style={accentVars(accent)}>
                {isEuro && h.table ? (
                  <div style={{ marginBottom: 14 }}>
                    <div className="lr-duel-h">Tabelle der Ligaphase</div>
                    <Table rows={h.table} leagueId="eu" compact />
                  </div>
                ) : null}
                {isCup ? (
                  <div className="lr-bracket">
                    {h.rounds.map((r) => (
                      <div key={r.name}>
                        <h4>{r.name}</h4>
                        {r.games.map((g, i) => (
                          <div className="g" key={i}>
                            <span>{g.h}</span>
                            <b>{g.hg}:{g.ag}{g.pen ? " n.E." : ""}</b>
                            <span>{g.a}</span>
                          </div>
                        ))}
                      </div>
                    ))}
                  </div>
                ) : (
                  <Table rows={h.table} leagueId={h.leagueId} compact />
                )}
                {h.type === "league" && h.unbeaten && h.unbeaten.length ? (
                  <div className="lr-duel-h" style={{ marginTop: 12 }}>
                    Längste Serie ohne Niederlage: {h.unbeaten[0].name}, {h.unbeaten[0].len} Spiele
                    ({h.unbeaten[0].from === h.unbeaten[0].to ? `${h.unbeaten[0].from}. Spieltag` : `${h.unbeaten[0].from}.–${h.unbeaten[0].to}. Spieltag`})
                  </div>
                ) : null}
                {h.scorers && h.scorers.length ? (
                  <div style={{ marginTop: 12 }}>
                    <div className="lr-duel-h">
                      Torschützenkönig: {h.scorers[0].name} ({h.scorers[0].verein}), {h.scorers[0].tore} Tore
                    </div>
                    <table className="lr-top-tbl">
                      <colgroup><col className="r" /><col /><col /><col className="g" /></colgroup>
                      <thead><tr><th /><th>Spieler</th><th className="v">Verein</th><th className="g">Tore</th></tr></thead>
                      <tbody>
                        {h.scorers.map((e, i) => (
                          <tr key={e.name + e.verein}>
                            <td className="r">{i + 1}</td>
                            <td>{e.name}</td>
                            <td className="v">{e.verein}{e.vorher ? <span className="vor">{e.vorher}</span> : null}</td>
                            <td className="g">{e.tore}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : null}
              </div>
            )}
          </div>
        );
      })}
      </div>
      ))}
    </>
  );
}


